function playAudioSafe(audioObj){
  try {
    if(!audioObj) return;
    const a = audioObj.cloneNode();
    a.volume = Number.isFinite(audioObj.volume) ? audioObj.volume : 1;
    a.play().catch(()=>{});
  } catch(e) {
    try { audioObj.pause(); audioObj.currentTime = 0; audioObj.play().catch(()=>{}); } catch(_e) {}
  }
}

