  async function buildBowserFrames() {
    try {
      const resp = await fetch(BOWSER_GIF_SRC);
      const buf = await resp.arrayBuffer();
      if ("ImageDecoder" in window) {
        const dec = new ImageDecoder({ data: buf, type: "image/gif" });
        await dec.tracks.ready;
        const track = dec.tracks.selectedTrack;
        const frameCount = track.frameCount || 1;
        bowserFrames = [];
        for (let i = 0; i < frameCount; i++) {
          const result = await dec.decode({ frameIndex: i });
          // result.image is an ImageBitmap
          bowserFrames.push(result.image);
        }
        bowserFramesReady = bowserFrames.length > 0;
      } else {
        bowserFramesReady = false;
      }
    } catch (e) {
      bowserFramesReady = false;
    }
  }
