    const dw = r.sw * scaleX;
    const dh = r.sh * scaleY;
    const bottomPad = (FRY_ATTACK_BOTTOM_PAD[frame] || 0) * scaleY;
    const dy = y + (r.sy - cellH) * scaleY + bottomPad;
