    if ((p.danyDragonLockT || 0) > 0 || (p.danyDragonCooldownT || 0) > 0) return true;
    STATE.danyDragons = STATE.danyDragons || [];
    p.specialAbilitySerial = (p.specialAbilitySerial || 0) + 1;
