    const bus = getFrizzleBusBox();
    const bus2 = (STATE.playerCount===2&&STATE.player2) ? getFrizzleBusBox(STATE.player2,STATE.selectedHorseRow2) : null;
    if (bus && hitBox.x <= bus.x + bus.w && hitBox.x + hitBox.w >= bus.x && hitBox.y <= bus.y + bus.h && hitBox.y + hitBox.h >= bus.y) return true;
    if (bus2 && hitBox.x <= bus2.x + bus2.w && hitBox.x + hitBox.w >= bus2.x && hitBox.y <= bus2.y + bus2.h && hitBox.y + hitBox.h >= bus2.y) return true;
