      t._customFreezeX=t.x;
      t._customFreezeY=t.y;
      t._customFreezeW=t.w||t.width||44;
      t._customFreezeH=t.h||t.height||44;
      STATE.frozenCustomEntities=STATE.frozenCustomEntities||[];
