      t._bagWebOwnerIndex=b.ownerIndex||1;
      t._bagWebTetherUntil=(STATE.time||0)+5.0;
      t.freezeCanStomp=true;
      t._freezeExplodeOnThaw=false;
      t.freezeT=5.0;
