  function chocolateKillRect(r,source){
    if(!r)return;
    for(const e of (STATE.enemies||[])){
      if(e.alive&&rectsOverlap(r,e)){e.alive=false;if(SFX&&SFX.pop)SFX.pop();}
    }
    for(const e of (STATE.piranhas||[])){
      if(e.alive&&rectsOverlap(r,e)){e.alive=false;if(SFX&&SFX.pop)SFX.pop();}
    }
    const custom=[STATE.lionRunner,STATE.raptorRunner,STATE.swampCreature,STATE.penguinRunner,STATE.fishRunner,STATE.pizzaMonster,STATE.marioRunner,STATE.warioRunner].filter(Boolean);
    for(const e of custom){
      if((e.alive!==false)&&(e.active!==false)&&rectsOverlap(r,{x:e.x,y:e.y,w:e.w||40,h:e.h||40})){
        if('active'in e)e.active=false;else e.alive=false;
        if('timer'in e)e.timer=5+Math.random()*4;
        if(SFX&&SFX.pop)SFX.pop();
      }
    }
    const boss=STATE.boss;
    STATE._oompaBossHitIds=STATE._oompaBossHitIds||new Set();
    const activationId=source&&source.id;
    if(boss&&boss.active&&!boss.defeated&&boss.type!=="tnt"&&boss.type!=="forcefield"&&!boss.shieldActive&&source&&activationId&&!STATE._oompaBossHitIds.has(activationId)&&rectsOverlap(r,{x:boss.x,y:boss.y,w:boss.w,h:boss.h})){
      boss.hp=Math.max(0,boss.hp-.25);boss.hitCooldown=Math.max(boss.hitCooldown||0,.35);STATE._oompaBossHitIds.add(activationId);
      if(boss.hp<=0){boss.defeated=true;STATE.bossFireballs.length=0;}
    }
  }
  function updateOompaChocolate(dt){
    const arr=STATE.oompaChocolate||[];
    const landedById=new Map();
    for(let i=arr.length-1;i>=0;i--){
      const o=arr[i];
      if(o.type==='bar'){
        o.life-=dt;o.vy+=o.g*dt;o.x+=o.vx*dt;o.y+=o.vy*dt;
        chocolateKillRect({x:o.x,y:o.y,w:o.w,h:o.h},o);
        let ground=STATE.groundY;
        for(const q of [...(STATE.platforms||[]),...(STATE.movingPlatforms||[]),...(STATE.qboxes||[])]){
          if(o.vy>0&&o.x+o.w>q.x&&o.x<q.x+q.w&&o.y+o.h>=q.y&&o.y+o.h<=q.y+28)ground=Math.min(ground,q.y);
        }
        if(o.vy>0&&o.y+o.h>=ground){
          arr[i]={type:'landmark',id:o.id,ownerIndex:o.ownerIndex,x:o.x+o.w/2,y:ground,t:.6};continue;
        }
        if(o.life<=0||o.y>canvas.height+150){arr.splice(i,1);continue;}
      }else if(o.type==='volcano'){
        o.t-=dt;o.shootT-=dt;chocolateKillRect({x:o.x,y:o.y,w:o.w,h:o.h},o);
        if(o.shootT<=0&&o.t>0){o.shootT=.18;for(const d of [-1,0,1])arr.push({type:'blob',id:o.id,source:o,x:o.x+o.w/2-7,y:o.y+8,w:14,h:14,vx:d*(135+Math.random()*45),vy:-270-Math.random()*85,g:690,t:.8,bossHit:o.bossHit});}
        if(o.t<=0){arr.splice(i,1);continue;}
      }else if(o.type==='blob'){
        o.t-=dt;o.vy+=o.g*dt;o.x+=o.vx*dt;o.y+=o.vy*dt;chocolateKillRect({x:o.x,y:o.y,w:o.w,h:o.h},o.source||o);
        if(o.t<=0||o.y>STATE.groundY+40)arr.splice(i,1);
      }else if(o.type==='particle'){
        o.t-=dt;o.vy+=o.g*dt;o.x+=o.vx*dt;o.y+=o.vy*dt;if(o.t<=0)arr.splice(i,1);
      }else if(o.type==='landmark'){
        o.t-=dt;
      }
    }
    const ids=[...new Set(arr.filter(o=>o.type==='landmark').map(o=>o.id))];
    for(const id of ids){
      const still=arr.some(o=>o.type==='bar'&&o.id===id);
      if(still)continue;
      const marks=arr.filter(o=>o.type==='landmark'&&o.id===id);
      if(!marks.length)continue;
      const x=marks.reduce((a,o)=>a+o.x,0)/marks.length;
      const y=marks.reduce((a,o)=>a+o.y,0)/marks.length;
      const ownerIndex=marks[0].ownerIndex;
      for(let j=arr.length-1;j>=0;j--)if(arr[j].type==='landmark'&&arr[j].id===id)arr.splice(j,1);
      spawnChocolateVolcano(id,x,y,ownerIndex);
    }
  }
