  // --- v36: T-Rex stomp + Donkey + Dragon fire ---
  function playerPowerPairs(){
    const out=[{p:STATE.player,row:STATE.selectedHorseRow,ownerIndex:1}];
    if(STATE.playerCount===2&&STATE.player2)out.push({p:STATE.player2,row:STATE.selectedHorseRow2,ownerIndex:2});
    return out;
  }

  function getTrexStompArea(p,baseRow){
    if(!p||getEffectiveCharacterRow(p,baseRow)!==35||(p.trexStompT||0)<=0)return null;
    return {cx:p.x+p.w*.5,cy:p.y+p.h,rx:235,ry:132,p,serial:p.specialAbilitySerial||0};
  }
  function trexAreaHitsRect(a,b){
    if(!a||!b)return false;
    const cx=clamp(a.cx,b.x,b.x+(b.w||0));
    const cy=clamp(a.cy,b.y,b.y+(b.h||0));
    const dx=(cx-a.cx)/a.rx,dy=(cy-a.cy)/a.ry;
    return dx*dx+dy*dy<=1;
  }
  function trexStompHitsRect(box){
    for(const it of playerPowerPairs()){
      const a=getTrexStompArea(it.p,it.row);
      if(a&&trexAreaHitsRect(a,box))return true;
    }
    return false;
  }

  // Dragon's sprite supplies the mouth flame. The damaging follow-up is now
  // strictly a SMALL three-flame trail that begins on the ground directly
  // beneath the end of the sprite flame and travels away from Dragon.
  function getDragonSurfaceYAtX(x,p){
    let surfaceY = Number.isFinite(STATE.groundY) ? STATE.groundY : ((p?.y||0)+(p?.h||0));
    const footY = (p?.y||0)+(p?.h||0);
    const surfaces=[...(STATE.platforms||[]),...(STATE.qboxes||[]),...(STATE.movingPlatforms||[])];
    for(const s of surfaces){
      if(!s || s.disabled) continue;
      if(x < s.x-8 || x > s.x+(s.w||0)+8) continue;
      // Only use a surface at/under the player's feet so an overhead platform
      // cannot pull the ground flames upward.
      if(s.y >= footY-18 && s.y < surfaceY) surfaceY=s.y;
    }
    return surfaceY;
  }

  function getDragonImpactPoint(p){
    if(!p)return null;
    const dir=p.facing>=0?1:-1;
    let reach=100;
    try{
      const extra=EXTRA_CHARACTERS[36];
      const frames=extra&&extra.fire;
      const img=frames&&frames.length ? (frames[frames.length-1]||frames[0]) : null;
      if(img&&img.complete&&img.naturalWidth&&img.naturalHeight){
        const dh=extra.fireDrawH||extra.drawH||94;
        const dw=dh*(img.naturalWidth/img.naturalHeight);
        const anchor=(extra.fireAnchorX ?? .36);
        // Right edge of the source fire sprite, mirrored automatically by dir.
        reach=Math.max(82,dw*(1-anchor)-7);
      }
    }catch(_){}
    // Start the follow-up flames a little closer to Dragon while preserving
    // about the same total reach by extending the later small flames farther.
    const x=p.x+p.w*.5+dir*Math.max(0,reach-15);
    return {x,y:getDragonSurfaceYAtX(x,p),dir};
  }

  function getDragonGroundFlameBox(f){
    if(!f || (f.delay||0)>0 || (f.life||0)<=0)return null;
    return {x:f.x-14,y:f.y-29,w:28,h:29,serial:f.attackSerial||0,ownerIndex:f.ownerIndex||1,flame:f};
  }

  function addDragonBurnEmoji(box){
    if(!box)return;
    STATE.dragonBurnEmojis=STATE.dragonBurnEmojis||[];
    const x=box.x+(box.w||0)*.5,y=box.y+(box.h||0)*.5;
    const now=STATE.time||0;
    if(STATE.dragonBurnEmojis.some(e=>Math.hypot(e.x-x,e.y-y)<18&&now-(e.spawnT||0)<.12))return;
    STATE.dragonBurnEmojis.push({x,y,t:.48,maxT:.48,spawnT:now});
  }

  function dragonFireHitsRect(box){
    if(!box)return false;
    for(const f of (STATE.dragonGroundFlames||[])){
      const b=getDragonGroundFlameBox(f);
      if(b&&rectsOverlapOrTouch(b,box,1)){addDragonBurnEmoji(box);return true;}
    }
    return false;
  }


  // === v73 additional F-sound pass ===
