  const V73_AHSOKA_F_SFX = new Audio(__CTEAM_ASSETS["assets/8a9e6617eeabb5524e99.mp3"]);
  const V73_MINION_F_SFX = new Audio(__CTEAM_ASSETS["assets/e20cfb4a3ecaa5f34160.mp3"]);
