  function playV73Audio(a){ try{ if(!a)return; a.pause&&a.pause(); a.currentTime=0; const q=a.play&&a.play(); if(q&&q.catch)q.catch(()=>{}); }catch(e){} }
  function playV73DonkeyStart(){playV73Audio(V73_DONKEY_START_SFX);}
