  function drawCarrot(c) {
    if (c.collected) return;
    const t = (STATE.time || 0);
    const seed = (c.x || 0) * 0.017 + (c.y || 0) * 0.031;
    const cx = c.x + c.w/2, cy = c.y + c.h/2;
    const pulse = 1 + 0.09 * Math.sin(t * 4.8 + seed);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(pulse, pulse);
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    // Warm glow behind the carrot so it reads clearly against every background.
    ctx.shadowColor = "rgba(255,225,80,0.98)";
    ctx.shadowBlur = 22 + 8 * (0.5 + 0.5*Math.sin(t*5.6 + seed));
    ctx.font = "30px system-ui,Segoe UI Emoji,Apple Color Emoji";
    ctx.fillText("🦩", 0, 0);
    ctx.shadowBlur = 0;

    // Three animated sparkles orbit the pickup without changing its hitbox.
    ctx.fillStyle = "rgba(255,255,210,0.98)";
    for (let i=0; i<3; i++) {
      const a = t * (1.7 + i*0.18) + seed + i * Math.PI * 2/3;
      const r = 22 + 5*Math.sin(t*3.1 + seed + i);
      const sx = Math.cos(a)*r, sy = Math.sin(a)*r*0.72;
      const tw = 1.5 + 2.2*(0.5+0.5*Math.sin(t*8.0 + seed + i*1.9));
      ctx.beginPath();
      ctx.moveTo(sx, sy-tw*2.2); ctx.lineTo(sx+tw, sy-tw);
      ctx.lineTo(sx+tw*2.2, sy); ctx.lineTo(sx+tw, sy+tw);
      ctx.lineTo(sx, sy+tw*2.2); ctx.lineTo(sx-tw, sy+tw);
      ctx.lineTo(sx-tw*2.2, sy); ctx.lineTo(sx-tw, sy-tw);
      ctx.closePath(); ctx.fill();
    }
    ctx.restore();
  }

  
