      if (row === 29 && firing) dw *= 1.15;

      let scale = 1;
      if (STATE.enteringPipe) scale = Math.max(0.2, 1 - STATE.pipeEnterT / 0.65);

      ctx.save();
      ctx.imageSmoothingEnabled = true;
      if(ctx.imageSmoothingEnabled){try{ctx.imageSmoothingQuality='high';}catch(_e){}}
      ctx.translate(screenCenterX, bottomY);
