      if(firing&&CHARACTER_NAMES[row]==='Skeletor'&&idx===frames.length-1)anchorX=.22;
      ctx.drawImage(img, -dw * anchorX, -dh, dw, dh);
      drawLeafAuraAroundPlayer(0, -dh / 2, dw, dh);
