    if(row===37){pc.font='30px system-ui';for(let i=0;i<4;i++){const x=125+((t*100+i*68)%250);pc.fillText('🐒',x,92+(i%2)*35);}pc.restore();return;}
    if(row===38){const x=120+Math.min(1,t/.8)*175;pc.font='32px system-ui';pc.fillText('🐸',x,145);pc.restore();return;}
    if(kind==='laser'){const x2=125+Math.min(1,t/.75)*180;profileDrawLineGlow(pc,112,128,x2,128,'rgba(255,35,35,.95)',5);pc.restore();return;}
