    if(kind==='patrickShorts'){pc.font='27px system-ui';for(let i=0;i<5;i++)pc.fillText('🩳',130+i*38,68+((t*115+i*32)%130));pc.restore();return;}
    if(kind==='scorpionHook'||kind==='cowboyHat'){const x=120+Math.min(1,t/.7)*170;profileDrawLineGlow(pc,110,142,x,142,'rgba(225,205,150,.95)',3);pc.restore();return;}
    if(kind==='card'){const x=120+Math.min(1,t/.8)*175;pc.save();pc.translate(x,137);pc.rotate(t*8);pc.fillStyle='#ff59c7';pc.fillRect(-10,-14,20,28);pc.restore();pc.restore();return;}
    if(kind==='heart'){pc.font='54px system-ui';pc.globalAlpha=.85+.15*Math.sin(t*10);pc.fillText('💗',anchorX,145);pc.restore();return;}
