    if(kind==='larryGoomba'){const x=120+Math.min(1,t/.9)*180;pc.fillStyle='#9a5b2e';pc.beginPath();pc.arc(x,178,17,Math.PI,0);pc.fill();pc.fillRect(x-14,178,28,20);pc.restore();return;}
    if(kind==='mintberryBurst'){const cx=anchorX,cy=145;for(let i=0;i<3;i++){const a=t*15+i*Math.PI*2/3;pc.fillStyle=i%2?'#b45de8':'#69f5cd';pc.beginPath();pc.arc(cx+Math.cos(a)*34,cy+Math.sin(a)*25,7,0,Math.PI*2);pc.fill();}pc.restore();return;}
    if(kind==='smooth'){pc.fillStyle='#fff';pc.font='28px system-ui';for(let i=0;i<6;i++){const a=t*8+i;pc.fillText('✦',145+Math.cos(a)*70,130+Math.sin(a)*50);}pc.restore();return;}
    if(kind==='detention'){const x=120+Math.min(1,t/.7)*150;pc.save();pc.translate(x,140);pc.rotate(-.15);pc.fillStyle='#d52020';pc.font='900 18px system-ui';pc.fillText('DETENTION',0,0);pc.restore();pc.restore();return;}
    if(kind==='megGrow'){pc.strokeStyle='rgba(255,255,255,.75)';pc.lineWidth=4;pc.beginPath();pc.arc(anchorX,150,42+Math.sin(t*6)*8,0,Math.PI*2);pc.stroke();pc.restore();return;}
    if(kind==='booOrbit'){pc.font='28px system-ui';for(let i=0;i<4;i++){const a=t*5+i*Math.PI/2;pc.fillText('👻',anchorX+Math.cos(a)*62,145+Math.sin(a)*42);}pc.restore();return;}
    if(kind==='psychic'){pc.strokeStyle='rgba(185,105,255,.9)';pc.lineWidth=5;for(let i=0;i<3;i++){const r=25+((t*55+i*28)%100);pc.globalAlpha=1-r/135;pc.beginPath();pc.arc(anchorX,145,r,0,Math.PI*2);pc.stroke();}pc.restore();return;}
    if(kind==='lobsterDrop'){pc.font='28px system-ui';for(let i=0;i<4;i++)pc.fillText('🦞',140+i*42,65+((t*110+i*38)%135));pc.restore();return;}
    if(kind==='saber'||kind==='mace'){pc.strokeStyle=kind==='mace'?'#ff7b22':'#bff7ff';pc.lineWidth=8;pc.beginPath();pc.arc(anchorX+20,145,60,-.8,.9);pc.stroke();pc.restore();return;}
    if(kind==='propane'||kind==='atomic'||kind==='dragonFire'){const grad=pc.createLinearGradient(115,0,300,0);grad.addColorStop(0,'rgba(255,230,80,.95)');grad.addColorStop(.5,'rgba(255,100,25,.9)');grad.addColorStop(1,'rgba(255,35,15,.1)');pc.fillStyle=grad;pc.beginPath();pc.moveTo(112,140);pc.lineTo(300,110);pc.lineTo(300,168);pc.closePath();pc.fill();pc.restore();return;}
