  // Contextual Action/Power helpers. O and V still fire powers normally; when a
  // player is standing on the completed pipe or next to TNT, the same button is
  // consumed by that context instead.
  function isV69PlayerOnPipe(p) {
    const pipe=STATE.pipe;
    if(!p||!pipe)return false;
    return p.onGround && p.y+p.h<=pipe.y+8 && (p.x+p.w*.5)>=pipe.x && (p.x+p.w*.5)<=(pipe.x+pipe.w) &&
      rectsOverlap({x:p.x,y:p.y,w:p.w,h:p.h+5},{x:pipe.x,y:pipe.y-5,w:pipe.w,h:pipe.h+10});
  }
  function isV69NearUsableTNT(p) {
    if(!p||!STATE.boss||!STATE.boss.active||STATE.boss.defeated||STATE.boss.type!=='tnt'||!STATE.tnts)return false;
    const pcx=p.x+p.w/2,pcy=p.y+p.h/2;
    return STATE.tnts.some(t=>!t.used&&Math.abs(pcx-(t.x+t.w/2))<90&&Math.abs(pcy-(t.y+t.h/2))<120);
  }
  function isV69ContextActionAvailable(p,playerIndex) {
    if(!p)return false;
    if(STATE.collected >= v552FlamingoGoal() && isV69PlayerOnPipe(p))return true;
    if(isV69NearUsableTNT(p))return true;
    return false;
  }

  // Definitely Not Kansas no longer carries the old space/gravity gimmicks.
  // It gets one clear, readable house hazard instead.
  const _v69InitEnvironmentMechanics = initEnvironmentMechanics;
  initEnvironmentMechanics = function(level,P,M) {
    _v69InitEnvironmentMechanics(level,P,M);
    if(level && level.key==='space' && STATE.environment) {
      const env=STATE.environment;
      env.gravityPulse=null;
      env.kansasHouse={crossed:false,phase:'idle',t:0,nextAt:0,targetX:0,startX:0,fallP:0,hit1:false,hit2:false,event:0};
      // Clear the old cosmic-only ambience/hazards so the board reads as Oz/Kansas.
      STATE.spaceComets=[];
      STATE.roadrunnerRunner=null;
      STATE.alienDrop=null;
      STATE.meteorStrike=null;
      STATE.officeWoodyThrowers=[];
    }
  };

  function v69LeadPlayerForHouse() {
    const a=STATE.player,b=(STATE.playerCount===2?STATE.player2:null);
    if(!b)return a;
    return ((b.x+b.w*.5)>(a.x+a.w*.5))?b:a;
  }
  function v69StartHouseWarning(h) {
    const lead=v69LeadPlayerForHouse();
    if(!lead)return;
    h.phase='warning';h.t=2.0;h.fallP=0;h.hit1=false;h.hit2=false;h.event=(h.event||0)+1;
    h.targetX=clamp(lead.x+lead.w*.5,170,STATE.worldW-170);
    // The airborne house begins up and to the right, then falls diagonally onto the locked shadow.
    h.startX=h.targetX+210;
    h.nextAt=(STATE.environment?.elapsed||0)+15.0;
  }
  function v69HouseHitBox(h) {
    const drawW=250,drawH=241;
    const groundTop=STATE.groundY-drawH;
    let cx=h.targetX,top=groundTop;
    if(h.phase==='fall'){
      const p=clamp(h.fallP||0,0,1);
      cx=h.startX+(h.targetX-h.startX)*p;
      top=(-drawH-45)+(groundTop-(-drawH-45))*p;
    }
    return {x:cx-92,y:top+33,w:184,h:182,cx,top};
  }
  function v69CheckHouseDamage(h) {
    if(!h||h.phase!=='fall')return;
    const hb=v69HouseHitBox(h);
    const p1=STATE.player;
    if(p1&&!h.hit1&&rectsOverlap({x:p1.x,y:p1.y,w:p1.w,h:p1.h},hb)){
      h.hit1=true;hurtPlayerFromEnvironment(hb.cx);
    }
    const p2=(STATE.playerCount===2?STATE.player2:null);
    if(p2&&!h.hit2&&rectsOverlap({x:p2.x,y:p2.y,w:p2.w,h:p2.h},hb)){
      h.hit2=true;
      if(!isChuckCharacter(p2,STATE.selectedHorseRow2))hurtPlayer2(hb.cx);
    }
  }
  const _v69UpdateEnvironmentMechanics=updateEnvironmentMechanics;
  updateEnvironmentMechanics=function(dt,p){
    _v69UpdateEnvironmentMechanics(dt,p);
    const env=STATE.environment,h=env&&env.key==='space'?env.kansasHouse:null;
    if(!h)return;
    const threshold=STATE.worldW*0.25;
    const lead=v69LeadPlayerForHouse();
    const leadX=lead?lead.x+lead.w*.5:0;
    if(!h.crossed && leadX>=threshold){h.crossed=true;v69StartHouseWarning(h);}
    if(!h.crossed)return;
    if(h.phase==='idle' && env.elapsed>=h.nextAt)v69StartHouseWarning(h);
    if(h.phase==='warning'){
      h.t-=dt;
      if(h.t<=0){h.phase='fall';h.t=1.08;h.fallP=0;}
    }else if(h.phase==='fall'){
      h.t-=dt;h.fallP=clamp(1-h.t/1.08,0,1);v69CheckHouseDamage(h);
      if(h.t<=0){h.phase='impact';h.t=.34;h.fallP=1;v69CheckHouseDamage(h);try{v70PlayHouseCrash();}catch(_e){}}
    }else if(h.phase==='impact'){
      v69CheckHouseDamage(h);h.t-=dt;if(h.t<=0){h.phase='ground';h.t=5.0;}
    }else if(h.phase==='ground'){
      h.t-=dt;if(h.t<=0){h.phase='idle';h.t=0;}
    }
  };

  // Kansas begins grayscale for exactly the first 1/4 of the world, then the
  // full-color Oz background takes over. We intentionally do not crossfade.
  const _v69DrawBackground=drawBackground;
  drawBackground=function(){
    if(STATE.levelKey!=='space')return _v69DrawBackground();
    const p=STATE.player;
    const inKansas=!!p && (p.x+p.w*.5)<STATE.worldW*.25;
    const levelImg=inKansas?V69_KANSAS_GRAY_IMG:LEVEL_BG_IMAGES.space;
    if(!levelImg||!levelImg.complete||!levelImg.naturalWidth){return _v69DrawBackground();}
    const scale=Math.max(canvas.width/levelImg.naturalWidth,canvas.height/levelImg.naturalHeight);
    const drawW=levelImg.naturalWidth*scale,drawH=levelImg.naturalHeight*scale;
    const extraX=Math.max(0,drawW-canvas.width),denom=Math.max(1,STATE.worldW-canvas.width);
    const progress=clamp(STATE.cameraX/denom,0,1),x=-extraX*progress,y=(canvas.height-drawH)/2;
    ctx.drawImage(levelImg,x,y,drawW,drawH);
    ctx.save();const wash=ctx.createLinearGradient(0,0,0,canvas.height);wash.addColorStop(0,'rgba(255,255,255,.06)');wash.addColorStop(1,'rgba(11,16,32,.08)');ctx.fillStyle=wash;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.restore();
  };

  const _v69DrawEnvironmentForeground=drawEnvironmentForeground;
  drawEnvironmentForeground=function(){
    _v69DrawEnvironmentForeground();
    const env=STATE.environment,h=env&&env.key==='space'?env.kansasHouse:null;
    if(!h||!h.crossed||h.phase==='idle'||!V69_FALLING_HOUSE_IMG.complete)return;
    const frameW=512,frameH=493,dw=250,dh=241;
    const drawCell=(frame,cx,top,rot=0,alpha=1)=>{
      ctx.save();ctx.globalAlpha=alpha;ctx.translate(cx-STATE.cameraX,top);if(rot){ctx.translate(0,dh*.5);ctx.rotate(rot);ctx.translate(0,-dh*.5);}ctx.drawImage(V69_FALLING_HOUSE_IMG,frame*frameW,0,frameW,frameH,-dw/2,0,dw,dh);ctx.restore();
    };
    const topGround=STATE.groundY-dh;
    if(h.phase==='warning'){
      const flash=.72+.28*Math.sin((env.elapsed||0)*15);
      drawCell(0,h.targetX,topGround,0,flash);
      drawEnvironmentWarning(`🏠 HOUSE! MOVE! ${Math.max(1,Math.ceil(h.t))}`);
    }else if(h.phase==='fall'){
      // Keep the locked warning shadow on the ground while the house approaches it.
      drawCell(0,h.targetX,topGround,0,.70);
      const hb=v69HouseHitBox(h);
      drawCell(1,hb.cx,hb.top,-.12*(1-(h.fallP||0)),1);
    }else if(h.phase==='impact'){
      drawCell(2,h.targetX,topGround,0,1);
    }else if(h.phase==='ground'){
      drawCell(3,h.targetX,topGround,0,Math.min(1,Math.max(.45,h.t/1.0)));
    }
  };

  // ------------------------------------------------------------------------
  // Character Profiles — three rows: dossier, mini Goomba-Gauntlet demo,
  // then replay/navigation. The demo is deliberately zoomed out and reuses
  // the exact gameplay F sprite frames/effect helper and sound routing.
  // ------------------------------------------------------------------------
  let v69ProfileSoundCycle=-1,v69ProfileSoundTimer=0;
  function v69ProfileSoundDelay(row){
    if(row===44)return .22; // Hermey: last toothbrush sprite
    if(row===23)return .25; // Shaq: last slam sprite
    if(row===35)return .34; // T-Rex: final stomp sprite
    return 0;
  }
  function v69CancelProfileSound(){if(v69ProfileSoundTimer){clearTimeout(v69ProfileSoundTimer);v69ProfileSoundTimer=0;}v69ProfileSoundCycle=-1;}
  function v69ScheduleProfileSound(row,cycleIndex){
    if(cycleIndex===v69ProfileSoundCycle)return;
    v69ProfileSoundCycle=cycleIndex;
    if(v69ProfileSoundTimer)clearTimeout(v69ProfileSoundTimer);
    const delay=v69ProfileSoundDelay(row);
    if(delay<=0){playProfileFSound(row);return;}
    v69ProfileSoundTimer=setTimeout(()=>{v69ProfileSoundTimer=0;const ov=document.getElementById('characterProfilesOverlay');if(ov&&ov.style.display!=='none')playProfileFSound(row);},delay*1000);
  }
  function v69DrawGoomba(pc,x,ground,t,mode='normal'){
    const w=44,h=55;
    pc.save();
    if(mode==='frozen'){pc.globalAlpha=.78;pc.fillStyle='rgba(120,220,255,.45)';pc.fillRect(x-w/2-5,ground-h-5,w+10,h+10);}
    if(mode==='webbed'){pc.strokeStyle='rgba(245,250,255,.95)';pc.lineWidth=1.5;for(let i=0;i<5;i++){pc.beginPath();pc.moveTo(x-w/2,ground-h+i*11);pc.lineTo(x+w/2,ground-h+(4-i)*11);pc.stroke();}}
    if(goombaSheet&&goombaSheet.complete&&goombaSheet.naturalWidth){const f=Math.floor(t*GOOMBA_FPS)%GOOMBA_FRAME_COUNT;pc.drawImage(goombaSheet,f*GOOMBA_FRAME_W,0,GOOMBA_FRAME_W,GOOMBA_FRAME_H,x-w/2,ground-h,w,h);}else{pc.fillStyle='#9a5b2e';pc.beginPath();pc.arc(x,ground-34,20,Math.PI,0);pc.fill();pc.fillRect(x-17,ground-34,34,30);}
    pc.restore();
  }
  function v69ProfileGoombaState(row,t,dur){
    const kind=getCharacterFPower(row).kind;
    let x=286,visible=true,mode='normal';
    if(row===42||row===56){const pull=Math.min(1,Math.max(0,(t-.25)/.65));x=286-(row===42?142:128)*pull;if(row===42&&pull>.20)mode='webbed';return{x,visible,mode};}
    if(kind==='snowball'||kind==='detention'){if(t>.55)mode='frozen';return{x,visible,mode};}
    if(row===26){if(t>.55)visible=false;return{x,visible,mode};}
    if([12,13,33,34,39,5,0].includes(row))return{x,visible,mode};
    let hitAt=.68;
    if([23,43,41,44,29,16,35].includes(row))hitAt=.45;
    if(row===17)hitAt=.85;
    if(row===19)hitAt=.60;
    if(row===45)hitAt=1.45;
    if(t>hitAt && t<dur-.20)visible=false;
    return{x,visible,mode};
  }

