  // BuildWorld is the last point where the legacy space-board actors are copied
  // into STATE. Clean those remnants here so Definitely Not Kansas cannot inherit
  // comets, the alien drop, or the meteor strike. Also explicitly restore every
  // regular platform in this board; the old space mechanics must never hide them.
  const _v70BuildWorld = buildWorld;
  buildWorld = function() {
    _v70BuildWorld();
    if (STATE.levelKey === 'space') {
      STATE.spaceComets = [];
      STATE.alienDrop = null;
      STATE.meteorStrike = null;
      for (const plat of (STATE.platforms || [])) {
        if (!plat._ghostPlatform && !plat._envErased) plat.disabled = false;
      }
      for (const plat of (STATE.movingPlatforms || [])) {
        if (!plat._ghostPlatform) plat.disabled = false;
      }
      if (STATE.environment) STATE.environment.gravityPulse = null;
    }
  };

  // --------------------------------------------------------------------------
  // Character Profiles: use the REAL game as the demonstration.
  // The normal game canvas runs a tiny controlled Goomba Gauntlet behind the
  // modal. The profile viewport mirrors that canvas, so character sprites, F
  // frames, projectiles, special effects, enemy reactions, and F sounds all come
  // from the exact same gameplay code instead of a separately invented preview.
  // --------------------------------------------------------------------------
  let v70ProfileDemoTimer = 0;
  let v70ProfileAttackTimer = 0;
  let v70ProfileDemoActive = false;

  function v70ClearProfileTimers() {
    if (v70ProfileDemoTimer) clearTimeout(v70ProfileDemoTimer);
    if (v70ProfileAttackTimer) clearTimeout(v70ProfileAttackTimer);
    v70ProfileDemoTimer = 0; v70ProfileAttackTimer = 0;
    try { STATE.keys['o'] = false; STATE.prevFire = false; } catch(_e) {}
  }
  function v70ProfileCycleDuration(row) {
    if ([0,5,12,13,18,25].includes(row)) return 6.8;
    if (row===17) return 3.45;
    if (row===45) return 3.35;
    if (row===42 || row===56) return 3.0;
    if (row===35 || row===36 || row===37) return 2.8;
    return 2.45;
  }
  function v70DemoGoombaX(row) {
    // Close-range powers need the Goomba in their actual gameplay hit zone.
    if ([8,16,18,23,29,35,41,43,44].includes(row)) return 315;
    if ([26,28].includes(row)) return 405;
    return 470;
  }
  function v70PrepareRealProfileWorld(row) {
    v70ClearProfileTimers();
    v70ProfileDemoActive = true;
    // Always demonstrate on the real first level.
    STATE.levelKey = 'goomba';
    STATE.levelLabel = 'Goomba Gauntlet';
    STATE.selectedHorseRow = row;
    STATE.selectedHorseRow2 = row;
    STATE.playerCount = 1;
    STATE.playerCountChosen = true;
    STATE.p1Team = [row];
    STATE.p1ActiveIndex = 0;
    STATE.firePower = true;
    _v70BuildWorld();
    STATE.screen = 'play';
    STATE.paused = false;
    STATE.cameraX = 0; STATE.cameraY = 0;
    STATE.collected = 0;
    STATE.invulnT = 999;
    STATE.flashT = 0;
    // Strip the demo down to exactly what the user asked to see: first-level
    // geometry, the selected player, and one actual Goomba.
    STATE.carrots = []; STATE.coins = []; STATE.qboxes = [];
    STATE.piranhas = []; STATE.piranhaFireballs = []; STATE.magicShots = [];
    STATE.officeWoodyThrowers = []; STATE.officeThrownPaperclips = [];
    STATE.officeGuestRunners = []; STATE.spaceComets = []; STATE.alienDrop = null; STATE.meteorStrike = null;
    STATE.roadrunnerRunner = null; STATE.bossFireballs = [];
    if (STATE.boss) { STATE.boss.active=false; STATE.boss.defeated=false; STATE.boss.x=STATE.worldW-900; }
    const p = STATE.player;
    if (p) {
      p.x = 175; p.y = STATE.groundY - p.h; p.vx = 0; p.vy = 0; p.onGround = true; p.facing = 1;
      p.safeX = p.x; p.safeY = p.y; p.fireAnimT = 0; p.playerFrozenT = 0;
    }
    const gx = v70DemoGoombaX(row);
    STATE.enemies = [{type:'goomba',x:gx,y:STATE.groundY-56,w:56,h:56,vx:0,minX:gx,maxX:gx,facing:-1,alive:true,noRespawn:true,freezeT:0}];
    // Fire through the actual P1 input route. This is what guarantees Randall's
    // 'Get over here', Hermey's delayed sound, Daenerys's two sounds, etc. stay
    // synchronized exactly as they are during gameplay.
    v70ProfileAttackTimer = setTimeout(()=>{
      if (!v70ProfileDemoActive || profileIndex!==row || STATE.screen!=='play') return;
      STATE.prevFire = false; STATE.keys['o'] = true;
      setTimeout(()=>{ try{STATE.keys['o']=false;}catch(_e){} }, 90);
    }, 360);
    v70ProfileDemoTimer = setTimeout(()=>{
      const ov=document.getElementById('characterProfilesOverlay');
      if(v70ProfileDemoActive && ov && ov.style.display!=='none' && profileIndex===row) v70PrepareRealProfileWorld(row);
    }, v70ProfileCycleDuration(row)*1000);
  }

