  function v71Ease(t) { t=clamp(t,0,1); return t*t*(3-2*t); }
  function v71CranePose(cr) {
    const warningDur = 5.43;
    const swingDur = 2.25;
    const pivotY = 34;
    const chainLen = Math.min(438, canvas.height*0.82);
    let pivotX = canvas.width * 0.50;
    let angle = 1.08;
    if (cr.phase < warningDur) {
      // During the backing-up sound, the crane slides into position from the right
      // and holds the ball visibly at the edge as the warning.
      const enter = v71Ease(cr.phase / 1.35);
      pivotX = (canvas.width + 190) + (canvas.width*0.50 - (canvas.width+190))*enter;
      angle = 1.08;
    } else if (cr.phase < warningDur + swingDur) {
      const t = v71Ease((cr.phase-warningDur)/swingDur);
      angle = 1.08 + (-2.16)*t;
    } else {
      angle = -1.08;
    }
    const ballX = pivotX + Math.sin(angle)*chainLen;
    const ballY = pivotY + Math.cos(angle)*chainLen;
    cr.pivotX=pivotX; cr.pivotY=pivotY; cr.ballX=ballX; cr.ballY=ballY; cr.angle=angle;
    return {pivotX,pivotY,ballX,ballY,angle,chainLen};
  }
  function v71CircleRectHit(cx,cy,r,box) {
    if (!box) return false;
    const nx=clamp(cx,box.x,box.x+box.w), ny=clamp(cy,box.y,box.y+box.h);
    const dx=cx-nx,dy=cy-ny; return dx*dx+dy*dy<=r*r;
  }

  const _v71UpdateEnvironmentMechanics = updateEnvironmentMechanics;
  updateEnvironmentMechanics = function(dt,p) {
    _v71UpdateEnvironmentMechanics(dt,p);
    const env=STATE.environment;
    const cr=env && env.key==='meadow' ? env.nycCrane : null;
    if (!cr) return;
    // Sentinel-style cadence: first event at 15 s, then every 15 s. The supplied
    // 5.43 s backing-up clip is the warning; the ball swings immediately after.
    if (env.elapsed < 15) {
      cr.visible=false; cr.warning=false; cr.swinging=false; cr.phase=0;
      return;
    }
    const warningDur=5.43, swingDur=2.25, holdDur=.55;
    const elapsed=env.elapsed-15;
    const cycle=Math.floor(elapsed/15);
    const ph=elapsed%15;
    if (cycle!==cr.cycle) {
      cr.cycle=cycle; cr.hit1=false; cr.hit2=false;
      v71PlayCraneBackupSfx();
    }
    cr.phase=ph;
    cr.warning=ph<warningDur;
    cr.swinging=ph>=warningDur && ph<warningDur+swingDur;
    cr.visible=ph<warningDur+swingDur+holdDur;
    if (!cr.visible) return;
    v71CranePose(cr);
    // The chain, pulley, and crane are visuals only. Damage is the circular ball.
    if (cr.swinging) {
      const p1=STATE.player;
      if (p1 && !cr.hit1 && STATE.invulnT<=0 && v71CircleRectHit(cr.ballX,cr.ballY,cr.radius-5,{x:p1.x-STATE.cameraX,y:p1.y,w:p1.w,h:p1.h})) {
        cr.hit1=true; hurtPlayerFromEnvironment(STATE.cameraX+cr.ballX);
      }
      const p2=(STATE.playerCount===2?STATE.player2:null);
      if (p2 && !cr.hit2 && STATE.invulnT2<=0 && !isChuckCharacter(p2,STATE.selectedHorseRow2) && v71CircleRectHit(cr.ballX,cr.ballY,cr.radius-5,{x:p2.x-STATE.cameraX,y:p2.y,w:p2.w,h:p2.h})) {
        cr.hit2=true; hurtPlayer2(STATE.cameraX+cr.ballX);
      }
    }
  };

  function v71DrawCraneHazard() {
    const env=STATE.environment,cr=env&&env.key==='meadow'?env.nycCrane:null;
    if (!cr || !cr.visible) return;
    const pose=v71CranePose(cr);
    const px=pose.pivotX,py=pose.pivotY,bx=pose.ballX,by=pose.ballY;
    ctx.save();
    // Construction-crane boom. It deliberately lives above the play field and
    // has no collision box.
    ctx.lineCap='round'; ctx.lineJoin='round';
    ctx.strokeStyle='#20252c'; ctx.lineWidth=18;
    ctx.beginPath();ctx.moveTo(px-175,py-18);ctx.lineTo(px+210,py-18);ctx.stroke();
    ctx.strokeStyle='#f0b51f'; ctx.lineWidth=12;
    ctx.beginPath();ctx.moveTo(px-175,py-18);ctx.lineTo(px+210,py-18);ctx.stroke();
    // Black warning stripes on the boom.
    ctx.strokeStyle='#25282d';ctx.lineWidth=7;
    for(let x=px-150;x<px+190;x+=42){ctx.beginPath();ctx.moveTo(x,py-27);ctx.lineTo(x+18,py-9);ctx.stroke();}
    // Pulley.
    ctx.fillStyle='#313740';ctx.beginPath();ctx.arc(px,py,21,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#9da4ad';ctx.lineWidth=4;ctx.beginPath();ctx.arc(px,py,13,0,Math.PI*2);ctx.stroke();
    // Chain links are purely visual.
    ctx.strokeStyle='#6f7781';ctx.lineWidth=5;ctx.shadowColor='rgba(0,0,0,.35)';ctx.shadowBlur=3;
    ctx.beginPath();ctx.moveTo(px,py+9);ctx.lineTo(bx,by);ctx.stroke();
    const dx=bx-px,dy=by-(py+9),dist=Math.hypot(dx,dy),links=Math.max(4,Math.floor(dist/25));
    for(let i=1;i<links;i++){
      const t=i/links,lx=px+dx*t,ly=(py+9)+dy*t;
      ctx.save();ctx.translate(lx,ly);ctx.rotate(Math.atan2(dy,dx));ctx.strokeStyle='rgba(170,176,185,.9)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,7,4,0,0,Math.PI*2);ctx.stroke();ctx.restore();
    }
    // Wrecking ball — the ONLY damaging part of the assembly.
    const g=ctx.createRadialGradient(bx-13,by-16,5,bx,by,cr.radius);
    g.addColorStop(0,'#9aa1aa');g.addColorStop(.28,'#59616b');g.addColorStop(1,'#171b21');
    ctx.fillStyle=g;ctx.shadowColor='rgba(0,0,0,.55)';ctx.shadowBlur=14;
    ctx.beginPath();ctx.arc(bx,by,cr.radius,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#0d1014';ctx.lineWidth=5;ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,.26)';ctx.beginPath();ctx.arc(bx-14,by-15,9,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }

