    const dir=p.facing>=0?1:-1;
    const sx=p.x-STATE.cameraX+p.w*(dir>0?.68:.32), sy=p.y+p.h*.38;
    const ex=sx+dir*62;
    const a=clamp((p.slimerBeamT||0)/.18,0,1);
