    ctx.fillStyle='rgba(75,255,105,.10)';ctx.strokeStyle='rgba(90,255,110,.78)';ctx.lineWidth=4;
    ctx.shadowColor='rgba(90,255,110,.95)';ctx.shadowBlur=16;
    ctx.beginPath();ctx.ellipse(cx,cy,Math.max(24,eb.w*.68),Math.max(26,eb.h*.68),0,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.restore();
