    const moving=Math.abs(p.vx)>20;
    const firing=(p.fireAnimT||0)>0&&extra.fire?.length;
    const flying=!!p.drTFlying;
    const postFlight=!!p.drTPostFlight&&extra.land;
    let img=null,dh=extra.walkDrawH||94,anchor=.5;
    if(firing){
      const total=.56,elapsed=Math.max(0,total-(p.fireAnimT||0));
      img=extra.fire[elapsed<.28?0:1]||extra.fire[0];dh=extra.fireDrawH||108;anchor=extra.fireAnchorX??.31;
    } else if(flying){
      if((p.drTTakeoffT||0)>0) img=extra.takeoff;
      else img=extra.fly[Math.floor((performance.now()/1000)*7)%extra.fly.length]||extra.fly[0];
      dh=70;anchor=extra.flyAnchorX??.5;
    } else if(postFlight){
      img=extra.land;dh=extra.landDrawH||82;
    } else {
      const frames=(moving?extra.run:extra.walk)||extra.walk;
      const idx=moving?Math.floor((p.animT||0)*2.4)%frames.length:0;
      img=frames[idx]||frames[0];dh=extra.walkDrawH||94;anchor=extra.walkAnchorX??.5;
    }
    if(!img||!img.complete||!img.naturalWidth||!img.naturalHeight)return false;
    const growthScale=clamp(STATE.playerScale||1,1,2);
    const cx=(p.x-STATE.cameraX)+p.w/2,by=p.y+p.h+10,dw=dh*(img.naturalWidth/img.naturalHeight);
    let sc=STATE.enteringPipe?Math.max(.2,1-STATE.pipeEnterT/.65):1;
    ctx.save();ctx.imageSmoothingEnabled=true;ctx.translate(cx,by);
