  // ========================================================================
  // v86 — Slimer possession visual/range + Dr. T final tuning pass
  // ========================================================================

  // Dr. T walk: another 2x slower than v85 (v85 was 2.4 -> now 1.2).
  if (EXTRA_CHARACTERS[46]) {
    EXTRA_CHARACTERS[46].walkSpeed = 1.2;
  }

  // Dr. T bomb: the thrown box and grounded box are both 2x the old v85 size.
  v74LaunchDrBomb = function(p, ownerIndex) {
    const dir = p.facing >= 0 ? 1 : -1;
    const w = 60, h = 56;
    STATE.drTBombs = STATE.drTBombs || [];
    STATE.drTBombs.push({
      x:p.x + p.w/2 + dir*46 - w/2,
      y:p.y + p.h*.31,
      w,h,
      thrownW:w,thrownH:h,
      vx:dir*230,
      vy:-120,
      dir,ownerIndex,player:p,
      stage:'falling',t:0,serial:p.specialAbilitySerial||0,done:false
    });
  };

  // Dr. T gravity behavior: every visible basic enemy is pulled toward the CENTER
  // of the grounded extra-credit box. Movement is clamped to the remaining distance,
  // so enemies cannot overshoot; once centered they are pinned there until detonation.
  v74UpdateBombs = function(dt) {
    const arr = STATE.drTBombs || [];
    const viewLeft=(STATE.cameraX||0)-20;
    const viewRight=(STATE.cameraX||0)+canvas.width+20;
    const viewTop=-80, viewBottom=canvas.height+100;

    for(let i=arr.length-1;i>=0;i--){
      const b=arr[i];
      b.t=(b.t||0)+dt;

      if(b.stage==='falling'){
        b.vy += 960*dt;
        b.x += b.vx*dt;
        b.y += b.vy*dt;
        const sy=v74SurfaceYAt(b.x+b.w/2,b.y);
        if(b.y+b.h>=sy){
          const cx=b.x+b.w/2;
          b.w=60; b.h=56; // keep the same 2x box size after landing
          b.x=cx-b.w/2;
          b.y=sy-b.h;
          b.vx=0; b.vy=0;
          b.stage='impact';
          b.t=0;
          v74PlayThud();
        }
      } else if(b.stage==='impact'){
        if(b.t>=.18){ b.stage='pull'; b.t=0; }
      } else if(b.stage==='pull'){
        const cx=b.x+b.w/2;
        const cy=b.y+b.h*.52;
        const entries=getAllBasicEnemyEntries();
        for(const en of entries){
          const e=en.e;
          if(!e || e.alive===false || e.active===false) continue;
          const eb=basicEnemyBox(e);
          const ex=eb.x+eb.w/2, ey=eb.y+eb.h/2;
          if(ex<viewLeft||ex>viewRight||ey<viewTop||ey>viewBottom) continue;

          // Target the box center horizontally. Ground enemies run to it; flying
          // enemies retain their normal vertical lane while being centered.
          const targetX=cx-eb.w/2;
          const dx=targetX-e.x;
          const normalSpeed=Math.max(80,Number(e.baseSpeed||e.speed||Math.abs(e.vx||0)||120));
          const speed=normalSpeed*1.25;
          const maxStep=speed*dt;

          if(Math.abs(dx)<=Math.max(2,maxStep)){
            e.x=targetX;
            if('vx' in e) e.vx=0;
            e._drTGravityPinned=true;
          } else {
            const s=Math.sign(dx);
            e.x += s*Math.min(Math.abs(dx),maxStep);
            if('vx' in e) e.vx=s*speed;
            e.facing=s>=0?1:-1;
            e._drTGravityPinned=false;
          }
        }

        if(b.t>=3.0){
          b.stage='explode'; b.t=0;
          playAudioSafe(V74_DR_T_EXPLODE);
          const r=265;
          for(const en of getAllBasicEnemyEntries()){
            const eb=basicEnemyBox(en.e), ex=eb.x+eb.w/2, ey=eb.y+eb.h/2;
            if(ex<viewLeft||ex>viewRight||ey<viewTop||ey>viewBottom) continue;
            if(Math.hypot(ex-cx,ey-cy)<=r) defeatBasicEntry(en);
          }
        }
      } else if(b.stage==='explode'){
        if(b.t>=.80){ b.done=true; arr.splice(i,1); }
      }
    }
  };

  // Redraw only Dr. T's bomb on top of the prior special-effect renderer.
