    const dir=p.facing>=0?1:-1;
    const ownerIndex=(p===STATE.player2)?2:1;
    const range=128;
    const box={
      x:dir>0?p.x+p.w*.58:p.x-range,
      y:p.y+p.h*.20,
      w:range,
      h:Math.max(30,p.h*.64)
    };
