  // Slimer possession alignment cleanup: keep possessed enemies on the player's
  // baseline, and lift flying Koopas a little so they do not sink below ground.
  v89SyncPossessedEnemy = function(p,e){
    if(!p||!e) return;
    const ew=Math.max(8,e.w||e.width||42);
    const eh=Math.max(8,e.h||e.height||42);
    e.x = p.x + (p.w - ew) * 0.5;
    let y = p.y + p.h - eh;
    if(e.type==='koopaFly') y -= Math.max(12, Math.round(eh*0.22));
    if(e.type==='lionRunner') y -= 4;
    e.y = y;
    e.vx = p.vx || 0;
    e.vy = p.vy || 0;
    e.facing = p.facing >= 0 ? 1 : -1;
    e._customFreezeUntil=(STATE.time||0)+.25;e._customFreezeKind='slimerPossession';e._customFreezeX=e.x;e._customFreezeY=e.y;
    if(e.type==='koopaFly') e.flipX = (e.facing < 0);
    if(e.alive!==false&&'active' in e)e.active=true;
  };

  function v91ApplyDrTGravityLock(dt){
    const pulls = (STATE.drTBombs||[]).filter(b => b && b.stage==='pull');
    if(!pulls.length) return;
    const viewLeft=(STATE.cameraX||0)-20;
    const viewRight=(STATE.cameraX||0)+canvas.width+20;
    const viewTop=-120, viewBottom=canvas.height+140;
    for(const b of pulls){
      const cx=b.x+b.w/2;
      const cy=b.y+b.h*.52;
      for(const entry of getAllBasicEnemyEntries()){
        const e=entry.e;
        if(!e || e.alive===false || e.active===false) continue;
        const eb=basicEnemyBox(e);
        const ex=eb.x+eb.w/2, ey=eb.y+eb.h/2;
        if(ex<viewLeft||ex>viewRight||ey<viewTop||ey>viewBottom) continue;
        const targetX = cx - eb.w/2;
        const targetY = cy - eb.h/2;
        const dx = targetX - e.x;
        const dy = targetY - e.y;
        const speed = Math.max(240, Number(e.baseSpeed||e.speed||Math.abs(e.vx||0)||140) * 1.6);
        const maxStep = speed * dt;
        const dist = Math.hypot(dx,dy);
        if(dist <= Math.max(3,maxStep)){
          e.x = targetX;
          e.y = targetY;
          e._drTGravityPinned = true;
        } else if(dist > 0) {
          e.x += dx / dist * maxStep;
          e.y += dy / dist * maxStep;
          e._drTGravityPinned = false;
        }
        if('vx' in e) e.vx = 0;
        if('vy' in e) e.vy = 0;
        if('facing' in e && Math.abs(dx) > 1) e.facing = dx >= 0 ? 1 : -1;
        if(e.type==='koopaFly') e.flipX = (e.facing < 0);
      }
    }
  }

