      if(!pl) continue;
      if(pl._v92MisfitFixedX==null){
        pl._v92MisfitFixedX=pl.x;
        pl._v92MisfitFixedY=pl.y;
      }
      pl.x=pl._v92MisfitFixedX;
      pl.y=pl._v92MisfitFixedY;
      pl.disabled=false;
      delete pl._ghostPlatform;
      delete pl._flowerPlatform;
      delete pl._envErased;
      delete pl._vineSwingStatic;
      delete pl.swingAmpX;
