  function v93UpdateKansasWitch(dt){
    if(STATE.levelKey!=='space') return;
    const p=STATE.player;
    if(!p) return;
    const threshold=STATE.worldW*.25;
    if((p.x+p.w*.5)>=threshold) v93SpawnKansasWitch();
    const w=STATE.kansasWitchEnemy;
    if(!w||!w.active||w.defeated) return;
    w.animT=(w.animT||0)+dt;
    w.hitCooldown=Math.max(0,(w.hitCooldown||0)-dt);
    const pc=p.x+p.w*.5,wc=w.x+w.w*.5;
    const dir=pc<wc?-1:1;
    w.facing=dir;
    // She pursues the player but stays on the ground plane so the encounter is readable.
    w.x+=dir*w.speed*dt;
    w.y=groundY-w.h-8+Math.sin((STATE.time||0)*5.6)*5;
    const hb={x:w.x+10,y:w.y+8,w:w.w-20,h:w.h-10};
    const defeatedByPower=tryFireballHitCustomEnemy(hb,()=>{w.active=false;w.defeated=true;if(typeof SFX!=='undefined'&&SFX.pop)SFX.pop();},w);
    if(defeatedByPower) return;
    const pb={x:p.x,y:p.y,w:p.w,h:p.h};
    if(rectsOverlap(pb,hb)){
      const stomp=(p.vy||0)>0 && (p.y+p.h*.72)<(w.y+w.h*.46);
      if(stomp){
        w.active=false;w.defeated=true;p.y=w.y-p.h;p.vy=-455;if(typeof SFX!=='undefined'&&SFX.pop)SFX.pop();
      }else if(STATE.invulnT<=0 && w.hitCooldown<=0){
        hurtPlayer(w.x+w.w*.5);w.hitCooldown=.8;
      }
    }
    const p2=(STATE.playerCount===2?STATE.player2:null);
    if(p2&&w.active&&rectsOverlap({x:p2.x,y:p2.y,w:p2.w,h:p2.h},hb)&&STATE.invulnT2<=0) hurtPlayer2(w.x+w.w*.5);
  }
  function v93DrawKansasWitch(){
    const w=STATE.kansasWitchEnemy;
    if(STATE.levelKey!=='space'||!w||!w.active||w.defeated) return;
    const ch=EXTRA_CHARACTERS[37];
    if(!ch||!ch.walk||!ch.walk.length) return;
    const img=ch.walk[Math.floor((w.animT||0)*(ch.fps||8))%ch.walk.length];
    if(!img||!img.complete||!img.naturalWidth) return;
    const sx=w.x-STATE.cameraX;
    ctx.save();ctx.imageSmoothingEnabled=true;
    if(w.facing<0){ctx.translate(sx+w.w/2,0);ctx.scale(-1,1);ctx.drawImage(img,-w.w/2,w.y,w.w,w.h);}
    else ctx.drawImage(img,sx,w.y,w.w,w.h);
    ctx.restore();
  }
