  STARTER_CHARACTER_ROWS.splice(0,STARTER_CHARACTER_ROWS.length,...V94_TOP_ROWS);
  getCharacterBoxes=function(){
    const topCols=7,pairCols=8;
    const topW=108,topH=46,topGap=7;
    const pairW=108,pairH=46,pairGapX=7,pairGapY=3;
    const topTotal=topCols*topW+(topCols-1)*topGap;
    const pairTotal=pairCols*pairW+(pairCols-1)*pairGapX;
    const topX=Math.round((canvas.width-topTotal)/2),topY=92;
    const gridX=Math.round((canvas.width-pairTotal)/2),gridY=141;
    const boxes=[];

    V94_TOP_ROWS.forEach((row,i)=>boxes.push({
      row,name:CHARACTER_NAMES[row],unlockReq:null,locked:false,group:'starter',
      x:topX+i*(topW+topGap),y:topY,w:topW,h:topH
    }));

    V94_PAIRED_ROWS.forEach((row,i)=>{
      const req=getUnlockRequirementForRow(row);
      boxes.push({
        row,name:CHARACTER_NAMES[row],unlockReq:req,locked:false,group:'level',
        x:gridX+(i%pairCols)*(pairW+pairGapX),
        y:gridY+Math.floor(i/pairCols)*(pairH+pairGapY),
        w:pairW,h:pairH
      });
    });

    // Any future character that was not in the 49-row authored roster goes at
    // the end without displacing the paired layout.
    const authored=new Set([...V94_TOP_ROWS,...V94_PAIRED_ROWS]);
    let extraIndex=V94_PAIRED_ROWS.length;
    for(let row=0;row<CHARACTER_NAMES.length;row++){
      if(authored.has(row)) continue;
      boxes.push({
        row,name:CHARACTER_NAMES[row],unlockReq:getUnlockRequirementForRow(row),locked:false,group:'level',
        x:gridX+(extraIndex%pairCols)*(pairW+pairGapX),
        y:gridY+Math.floor(extraIndex/pairCols)*(pairH+pairGapY),
        w:pairW,h:pairH
      });
      extraIndex++;
    }
    return boxes;
  };

