  // ------------------------------------------------------------------------
  // Special recharge state + HUD.
  // Cooldowns are stored PER PLAYER and PER CHARACTER, so swapping out and
  // back cannot reset a meter.
  // ------------------------------------------------------------------------
  function v97CooldownMap(p){if(!p)return{};if(!p._v97SpecialCooldowns)p._v97SpecialCooldowns={};return p._v97SpecialCooldowns;}
  function v97CooldownRemaining(p,row){return Math.max(0,Number(v97CooldownMap(p)[row]||0));}
  function v97SpecialReady(p,row){return row===39||v97RechargeSeconds(row)===0||v97CooldownRemaining(p,row)<=0;}
  function v97StartRecharge(p,row){const sec=v97RechargeSeconds(row);if(row===39||sec<=0){v97CooldownMap(p)[row]=0;return;}v97CooldownMap(p)[row]=sec;}
  function v97TickRecharge(p,dt){if(!p)return;const m=v97CooldownMap(p);for(const k of Object.keys(m)){const row=Number(k);if(v97RechargeSeconds(row)<=0)m[k]=0;else m[k]=Math.max(0,(Number(m[k])||0)-dt);}}

  const V97_LEGACY_COOLDOWN_FIELDS=['amyHeartCooldownT','bobEraserCooldownT','busSweepCooldownT','cactusCooldownT','danyDragonCooldownT','dragonFireCooldownT','hermeyToothCooldownT','horsePoopCooldownT','leafAuraCooldownT','luckyRainbowCooldownT','minionArmyCooldownT','mystiquePowerCooldownT','scoobyBuffCooldownT','shareBearCooldownT','slimerBeamCooldownT','snapePowerCooldownT','trexStompCooldownT','witchPowerCooldownT'];
  function v97ReleaseLegacyCooldownsWhenReady(p,row){if(!p||!v97SpecialReady(p,row))return;for(const f of V97_LEGACY_COOLDOWN_FIELDS)if(f in p)p[f]=0;}

  function v97EnsureSpecialHUD(){
    if(document.getElementById('v97SpecialHudP1'))return;
    v97InstallInfoStyles();
    function wrap(score,id,isP2){
      if(!score||score.parentElement?.classList?.contains('v97ScoreStack'))return;
      const stack=document.createElement('div');stack.className='v97ScoreStack'+(isP2?' p2':'');stack.id=id+'Stack';score.parentNode.insertBefore(stack,score);stack.appendChild(score);
      const hud=document.createElement('div');hud.id=id;hud.className='v97SpecialHud';hud.innerHTML='<span class="v97SpecialS">S</span><span class="v97SpecialTrack"><span class="v97SpecialFill"></span></span>';stack.appendChild(hud);
    }
    wrap(scoreEl,'v97SpecialHudP1',false);wrap(score2El,'v97SpecialHudP2',true);
  }
  function v97UpdateOneHUD(id,p,row){
    const el=document.getElementById(id);if(!el||!p)return;const total=v97RechargeSeconds(row),rem=v97CooldownRemaining(p,row);const ready=v97SpecialReady(p,row);const frac=(row===39||total<=0)?1:clamp(1-rem/total,0,1);const f=el.querySelector('.v97SpecialFill');if(f)f.style.width=(frac*100).toFixed(1)+'%';el.classList.toggle('ready',ready);
    el.title=row===39?'Chuck Norris is always ready.':`${CHARACTER_NAMES[row]} Special: ${ready?'READY':Math.ceil(rem)+'s'}`;
  }
  function v97UpdateSpecialHUD(){
    v97EnsureSpecialHUD();
    v97UpdateOneHUD('v97SpecialHudP1',STATE.player,STATE.selectedHorseRow);
    const p2Stack=document.getElementById('v97SpecialHudP2Stack');if(p2Stack)p2Stack.style.display=STATE.playerCount===2?'flex':'none';
    if(STATE.playerCount===2&&STATE.player2)v97UpdateOneHUD('v97SpecialHudP2',STATE.player2,STATE.selectedHorseRow2);
  }
  const V97_PREV_UPDATE_HUD=updateHUD;
  updateHUD=function(){const r=V97_PREV_UPDATE_HUD();v97UpdateSpecialHUD();return r;};

  // ------------------------------------------------------------------------
  // Range application: projectiles inherit a travel distance based on stars;
  // close/area attacks extend their practical affected region accordingly.
  // ------------------------------------------------------------------------
  const V97_PROJECTILE_ROWS=new Set([1,3,4,6,7,9,10,11,15,22,24,27,30,31,32,36,37,38,40,42,45,48]);
  const V97_NONDAMAGE_ROWS=new Set([0,5,11,12,13,39,47,48]);
  const V97_DIRECTIONAL_AREA_ROWS=new Set([16,18,21,24,26,29,35,41,43,44]);
  function v97SnapshotSpecialArrays(){return{fireballs:(STATE.fireballs||[]).length,rainbows:(STATE.luckyRainbows||[]).length,flames:(STATE.dragonGroundFlames||[]).length,lobsters:(STATE.zoidbergLobsters||[]).length};}
  function v97TagNewSpecialObjects(p,row,owner,before){
    const range=v97RangePixels(row);
    for(let i=before.fireballs;i<(STATE.fireballs||[]).length;i++){
      const b=STATE.fireballs[i];if(!b)continue;b._v97PowerRow=row;b.ownerIndex=b.ownerIndex||owner;
      if(Number.isFinite(b.vx)&&Math.abs(b.vx)>1){b.maxTravel=Math.max(70,range);const need=range/Math.abs(b.vx)+.22;b.life=Math.max(b.life||0,need);b.maxLife=Math.max(b.maxLife||0,need);}
    }
    for(let i=before.lobsters;i<(STATE.zoidbergLobsters||[]).length;i++){const b=STATE.zoidbergLobsters[i];if(b){b._v97PowerRow=row;b.ownerIndex=owner;}}
    for(let i=before.rainbows;i<(STATE.luckyRainbows||[]).length;i++){
      const q=STATE.luckyRainbows[i];if(!q)continue;const cx=q.x+q.w/2;q.w=Math.max(q.w||0,range);q.x=cx-q.w/2;q._v97PowerRow=row;
    }
    for(let i=before.flames;i<(STATE.dragonGroundFlames||[]).length;i++){const f=STATE.dragonGroundFlames[i];if(f){f._v97PowerRow=row;f.ownerIndex=owner;}}
  }
  function v97KillEntry(entry){const e=entry?.e;if(!e)return;if('alive' in e)e.alive=false;else if('active' in e)e.active=false;try{if(SFX&&SFX.pop)SFX.pop();}catch(_e){}}
  function v97ApplyAreaRange(p,row){
    if(!p||V97_NONDAMAGE_ROWS.has(row)||V97_PROJECTILE_ROWS.has(row))return;
    const reach=v97RangePixels(row),cx=p.x+p.w/2,cy=p.y+p.h/2,dir=p.facing>=0?1:-1;
    for(const entry of getAllBasicEnemyEntries()){
      const e=entry.e;if(!e||e.alive===false||e.active===false||e._slimerPossessedBy)continue;const b=basicEnemyBox(e),ex=b.x+b.w/2,ey=b.y+b.h/2;let hit=false;
      if(V97_DIRECTIONAL_AREA_ROWS.has(row)){const dx=(ex-cx)*dir;hit=dx>=-25&&dx<=reach&&Math.abs(ey-cy)<=Math.max(95,p.h*1.8);}
      else hit=Math.hypot(ex-cx,ey-cy)<=Math.max(75,reach*.52);
      if(hit)v97KillEntry(entry);
    }
  }

  // Dr. T's gravity pull respects his four-star (~3/4 screen) effective range.
  v91ApplyDrTGravityLock=function(dt){
    const pulls=(STATE.drTBombs||[]).filter(b=>b&&b.stage==='pull');if(!pulls.length)return;const range=v97RangePixels(46);
    const viewLeft=(STATE.cameraX||0)-20,viewRight=(STATE.cameraX||0)+canvas.width+20,viewTop=-120,viewBottom=canvas.height+140;
    for(const b of pulls){const cx=b.x+b.w/2,cy=b.y+b.h*.52;
      for(const entry of getAllBasicEnemyEntries()){const e=entry.e;if(!e||e.alive===false||e.active===false)continue;const eb=basicEnemyBox(e),ex=eb.x+eb.w/2,ey=eb.y+eb.h/2;if(ex<viewLeft||ex>viewRight||ey<viewTop||ey>viewBottom||Math.abs(ex-cx)>range)continue;
        const tx=cx-eb.w/2,ty=cy-eb.h/2,dx=tx-e.x,dy=ty-e.y,speed=Math.max(240,Number(e.baseSpeed||e.speed||Math.abs(e.vx||0)||140)*1.6),maxStep=speed*dt,dist=Math.hypot(dx,dy);
        if(dist<=Math.max(3,maxStep)){e.x=tx;e.y=ty;e._drTGravityPinned=true;}else if(dist>0){e.x+=dx/dist*maxStep;e.y+=dy/dist*maxStep;e._drTGravityPinned=false;}
        if('vx'in e)e.vx=0;if('vy'in e)e.vy=0;if('facing'in e&&Math.abs(dx)>1)e.facing=dx>=0?1:-1;if(e.type==='koopaFly')e.flipX=e.facing<0;
      }
    }
  };

  // ------------------------------------------------------------------------
  // Final simulation wrapper: exact special gating/recharge, jump stats,
  // platform reassertion, and smooth HUD refresh.
  // ------------------------------------------------------------------------
  const V97_PREV_STEP=step;
  let V97_HELD_O=false,V97_HELD_V=false,V97_HELD_P=false,V97_HELD_C=false;
  step=function(dt){
    const p1=STATE.player,p2=STATE.player2,row1=STATE.selectedHorseRow,row2=STATE.selectedHorseRow2;
    v97TickRecharge(p1,dt);v97TickRecharge(p2,dt);v97ReleaseLegacyCooldownsWhenReady(p1,row1);v97ReleaseLegacyCooldownsWhenReady(p2,row2);

    const physO=!!STATE.keys?.o,physV=!!STATE.keys?.v,physP=!!STATE.keys?.p,physC=!!STATE.keys?.c;
    const edgeO=physO&&!V97_HELD_O,edgeV=physV&&!V97_HELD_V,edgeP=physP&&!V97_HELD_P,edgeC=physC&&!V97_HELD_C;
    const context1=p1?isV69ContextActionAvailable(p1,1):false,context2=p2?isV69ContextActionAvailable(p2,2):false;
    const allowO=context1||(edgeO&&v97SpecialReady(p1,row1));
    const allowV=context2||(edgeV&&v97SpecialReady(p2,row2));
    const before1=v97SnapshotSpecialArrays(),before2={...before1};
    if(STATE.keys){STATE.keys.o=allowO?physO:false;STATE.keys.v=allowV?physV:false;}

    const p1OnGround=!!p1?.onGround,p2OnGround=!!p2?.onGround;
    V97_PREV_STEP(dt);

    // Jump stat scales the actual launch velocity after the existing jump code
    // has done all board-specific and character-specific checks.
    if(p1&&edgeP&&p1OnGround&&p1.vy<0){const mul=V97_JUMP_REL[v535JumpStars(p1,row1)]||1;p1.vy*=mul;}
    if(p2&&edgeC&&p2OnGround&&p2.vy<0){const mul=V97_JUMP_REL[v535JumpStars(p2,row2)]||1;p2.vy*=mul;}

    if(edgeO&&!context1&&allowO&&p1&&STATE.firePower){v97StartRecharge(p1,row1);v97TagNewSpecialObjects(p1,row1,1,before1);v97ApplyAreaRange(p1,row1);}
    if(edgeV&&!context2&&allowV&&p2&&STATE.firePower){v97StartRecharge(p2,row2);v97TagNewSpecialObjects(p2,row2,2,before2);v97ApplyAreaRange(p2,row2);}

    // Restore physical key state so input handling outside simulation sees the
    // real keyboard, not the temporary recharge gate.
    if(STATE.keys){STATE.keys.o=physO;STATE.keys.v=physV;}
    V97_HELD_O=physO;V97_HELD_V=physV;V97_HELD_P=physP;V97_HELD_C=physC;

    v94EnsureHorizontalPlatforms(STATE.levelKey);if(STATE.levelKey==='snow')v94EnsureSnowJellyGuns();
    // Fallback: if an unusual hit route raises invulnerability without calling
    // hurtPlayer, possession still ends immediately.
    if(p1?.slimerPossessing&&(STATE.invulnT||0)>0)v85ExitPossession(p1,true);
    if(p2?.slimerPossessing&&(STATE.invulnT2||0)>0)v85ExitPossession(p2,true);
    v97UpdateSpecialHUD();
  };

