  function v98PlaceProfileStats(){
    const loc=document.getElementById('profileLocation');
    const stats=document.getElementById('profileStats');
    if(!loc || !stats) return;

    let wrap=document.getElementById('profileStatsWrap');
    if(!wrap){
      wrap=document.createElement('div');
      wrap.id='profileStatsWrap';
      wrap.style.marginTop='10px';
      wrap.innerHTML='<div style="opacity:.62;font:800 10px system-ui;letter-spacing:.12em;">STATS</div>';
    }

    const grid = loc.parentElement ? loc.parentElement.parentElement : null;
    const leftBlock = grid ? grid.parentElement : null;
    if(leftBlock){
      if(wrap.parentElement!==leftBlock) leftBlock.appendChild(wrap);
      if(stats.parentElement!==wrap) wrap.appendChild(stats);
      stats.style.marginTop='6px';
    }
  }

