  // A webbed Bag-Man target is a setup, not an automatic kill: Bag-Man must
  // jump on the tethered enemy to finish it. This universal pass also covers
  // custom runners/hazards, not only the standard STATE.enemies array.
  function v115BagWebTargetIsStompable(e){
    if(!e) return false;
    const now=STATE.time||0;
    return (e._bagWebTetherUntil||0)>now ||
           (e.freezePowerKind==='webLasso' && (e.freezeT||0)>0) ||
           (e._customFreezeKind==='webTether' && (e._customFreezeUntil||0)>now);
  }
  function v115TryBagWebStomp(p,row,prevY){
    if(!p || getEffectiveCharacterRow(p,row)!==42 || (p.vy||0)<0) return false;
    const prevBottom=(Number.isFinite(prevY)?prevY:p.y)+p.h;
    const pb={x:p.x,y:p.y,w:p.w,h:p.h};
    for(const entry of getAllBasicEnemyEntries()){
      const e=entry.e;
      if(!v115BagWebTargetIsStompable(e)) continue;
      const eb=basicEnemyBox(e);
      // Crossing the upper portion of the enemy counts as the stomp. The
      // slightly generous margin keeps the reel-in position from making it
      // frustrating to land on the target.
      const crossedTop=prevBottom<=eb.y+26 && (p.y+p.h)>=eb.y;
      const horizontal=p.x+p.w>eb.x+4 && p.x<eb.x+eb.w-4;
      if(!crossedTop || !horizontal) continue;
      e._bagWebTetherUntil=0;
      e._bagWebPulled=false;
      e._randallCaptured=false;
      e.freezeT=0;
      e.freezePowerKind=null;
      e.freezeVisual=null;
      e.freezeCanStomp=false;
      e._customFreezeUntil=0;
      e._customFreezeKind=null;
      defeatBasicEntry(entry);
      p.y=eb.y-p.h;
      p.vy=-360;
      return true;
    }
    return false;
  }
