  function v116DoubleOfficeEnemies(){
    if(STATE.levelKey!=='office'||STATE._v116OfficeDoubled)return;
    STATE._v116OfficeDoubled=true;
    const guests=(STATE.officeGuestRunners||[]).slice();
    for(const gr of guests){
      const c={...gr,active:true,timer:0,row:pickOfficeRunnerRow(),dir:(gr.dir||-1)*-1,animT:0};
      c.x=STATE.cameraX+((c.dir||-1)<0?canvas.width+c.w+30:-c.w-30);
      c.y=STATE.groundY-c.h; c.baseY=c.y;
      STATE.officeGuestRunners.push(c);
    }
    const base=(STATE.enemies||[]).filter(e=>e&&(e.type==='ottoRunner'||e.type==='hawkFly')).slice();
    for(const e of base){
      const c={...e,alive:true,noRespawn:true,animT:0};
      c.x=Math.min(STATE.worldW-500,Math.max(300,(e.x||500)+220));
      if(Number.isFinite(c.minX))c.minX=Math.min(STATE.worldW-600,c.minX+180);
      if(Number.isFinite(c.maxX))c.maxX=Math.min(STATE.worldW-300,c.maxX+180);
      if('phase' in c)c.phase=(c.phase||0)+1.7;
      STATE.enemies.push(c);
    }
  }

