    music.onloadedmetadata=()=>{const target=(Number.isFinite(music.duration)&&music.duration>0)?music.duration*.75:96;music.ontimeupdate=()=>{if(music.currentTime>=target)switchToOffice();};};
    music.onended=switchToOffice;try{music.load();}catch(_e){}music.play().catch(()=>{});
