  // ========================================================================
  // v120 — Dr. T gravity reliability + Office Dr. T flight cycle + Chuck audio QA
  // ========================================================================

  // Chuck's clips were already at browser volume 1, so simply setting volume
  // higher could not make them louder.  Stack synchronized copies instead.
  // Existing callers still pass 1.5; Chuck-specific clips are promoted to 3x.
  v117PlayBoostedAudio = function(audio, boost=1.5){
    if(!audio) return;
    try{
      const isChuck = audio===V116_CHUCK_DEFEAT_LINE ||
                      audio===CHUCK_ROUNDHOUSE_SFX ||
                      audio===V72_CHUCK_ONLY_F_SFX ||
                      audio===CHUCK_HURT_SFX_V66;
      const target = Math.max(1, isChuck ? 3 : Number(boost||1));
      audio.pause();
      audio.currentTime=0;
      audio.volume=1;
      audio.play().catch(()=>{});
      if(!audio.src) return;
      let remaining=target-1;
      while(remaining>0.001){
        const clone=audio.cloneNode(true);
        clone.volume=Math.min(1,remaining);
        clone.currentTime=0;
        clone.play().catch(()=>{});
        remaining-=1;
      }
    }catch(_e){}
  };

  // Dr. T had THREE competing damage/pull systems: the old v91 range lock,
  // the generic v97 area attack, and the later bomb vacuum.  Make the gravity
  // bomb the single authority so pressing the Action button never arbitrarily deletes enemies.
  try{v91ApplyDrTGravityLock=function(){};}catch(_e){}
  const V120_PREV_AREA_RANGE=v97ApplyAreaRange;
  v97ApplyAreaRange=function(p,row){
    if(Number(row)===46) return;
    return V120_PREV_AREA_RANGE(p,row);
  };

  function v120IsEntityActive(e){
    return !!e && e.alive!==false && e.active!==false && !e.defeated;
  }
  function v120EntityOnScreen(e, margin=80){
    if(!e) return false;
    const b=basicEnemyBox(e);
    const left=STATE.cameraX||0, right=left+canvas.width;
    return b.x+b.w>=left-margin && b.x<=right+margin &&
           b.y+b.h>=-margin && b.y<=canvas.height+margin;
  }
  function v120FindCapture(b,e){
    return (b._v120Captured||[]).find(c=>c&&c.e===e)||null;
  }
  function v120AddCapture(b,e,kind,entry=null){
    if(!b||!e||v120FindCapture(b,e)) return;
    b._v120Captured=b._v120Captured||[];
    b._v120Captured.push({
      e, kind, entry,
      oldRandall:!!e._randallCaptured,
      oldDrTNoTouch:e._drTNoTouchUntil||0,
      pinX:e.x||0, pinY:e.y||0,
      pinned:false
    });
  }
  function v120CollectVisibleHostiles(b){
    for(const entry of getAllBasicEnemyEntries()){
      const e=entry&&entry.e;
      if(!v120IsEntityActive(e)||!v120EntityOnScreen(e,65)) continue;
      v120AddCapture(b,e,'basic',entry);
    }
    const main=STATE.boss;
    if(main&&main.active&&!main.defeated&&!main._v116WalkOff&&v120EntityOnScreen(main,65))
      v120AddCapture(b,main,'boss',null);
    const side=STATE.sideBoss;
    if(side&&side.active&&!side.defeated&&!side.dropping&&v120EntityOnScreen(side,65))
      v120AddCapture(b,side,'subboss',null);
  }
  function v120MoveCaptureTowardBomb(b,c,dt){
    const e=c&&c.e;
    if(!e||!v120IsEntityActive(e)) return;
    const eb=basicEnemyBox(e);
    const cx=b.x+b.w/2, cy=b.y+b.h*.52;
    const tx=cx-eb.w/2, ty=cy-eb.h/2;
    let x=Number.isFinite(c.pinX)?c.pinX:(e.x||0);
    let y=Number.isFinite(c.pinY)?c.pinY:(e.y||0);
    const dx=tx-x,dy=ty-y,dist=Math.hypot(dx,dy);
    const maxStep=1250*Math.max(0,dt||0);
    if(c.pinned || dist<=Math.max(12,maxStep)){
      x=tx;y=ty;c.pinned=true;
    }else if(dist>0){
      x+=dx/dist*maxStep;
      y+=dy/dist*maxStep;
    }
    c.pinX=x;c.pinY=y;
    e.x=x;e.y=y;
    // Pause movement/contact while the victim is being vacuumed, but do not
    // alter its dimensions or visibility.
    e._randallCaptured=true;
    e._drTNoTouchUntil=(STATE.time||0)+.40;
    if('vx' in e)e.vx=0;
    if('vy' in e)e.vy=0;
    if(c.kind==='basic'){
      if('fireT' in e)e.fireT=Math.max(Number(e.fireT)||0,9999);
      if('fireAnimT' in e)e.fireAnimT=0;
    }
  }
  function v120ReleaseCapture(c){
    const e=c&&c.e;if(!e)return;
    e._randallCaptured=!!c.oldRandall;
    e._drTNoTouchUntil=Math.max(c.oldDrTNoTouch||0,(STATE.time||0)+.08);
    e._v120DrTCaptured=false;
  }
  function v120ResolveCapturedBoss(c){
    const e=c&&c.e;if(!e||e.defeated)return;
    // Respect the v119 boss contract.  A gravity bomb is still an F power:
    // TNT/field/sub-bosses take no damage; 6-HP jump bosses take exactly .25.
    if(c.kind==='boss'&&e._v119BossClass==='doublejump'){
      e.hp=Math.max(0,(Number(e.hp)||0)-.25);
      e.hitCooldown=Math.max(e.hitCooldown||0,.35);
      try{playCharacterHitSfx(e.row);}catch(_e){}
      if(e.hp<=0){e.defeated=true;STATE.bossFireballs.length=0;}
    }else if(c.kind==='boss'&&e._v119BossClass==='forcefield'){
      e._v119ForcedShieldT=Math.max(e._v119ForcedShieldT||0,3);
      e.shieldActive=true;
    }
  }
  function v120ExplodeGravityBomb(b){
    for(const c of (b._v120Captured||[])){
      const e=c&&c.e;if(!e)continue;
      if(c.kind==='basic'){
        if(v120IsEntityActive(e)) defeatBasicEntry(c.entry||findBasicEnemyEntryForEntity(e));
      }else{
        v120ResolveCapturedBoss(c);
        v120ReleaseCapture(c);
      }
    }
    b._v120Captured=[];
  }
  function v120PinGravityCaptures(){
    for(const b of (STATE.drTBombs||[])){
      if(!b||b.stage!=='pull')continue;
      for(const c of (b._v120Captured||[])){
        const e=c&&c.e;if(!e||!v120IsEntityActive(e))continue;
        e.x=c.pinX;e.y=c.pinY;
        e._randallCaptured=true;
        e._drTNoTouchUntil=(STATE.time||0)+.40;
        if('vx'in e)e.vx=0;
        if('vy'in e)e.vy=0;
      }
    }
  }

  // Authoritative Dr. T bomb simulation: every hostile currently visible is
  // pulled to the exact center, remains visible there, and is resolved only
  // when the Extra Credit box explodes.  Nothing disappears on contact early.
  v74UpdateBombs=function(dt){
    const arr=STATE.drTBombs||[];
    for(let i=arr.length-1;i>=0;i--){
      const b=arr[i];
      b.t=(b.t||0)+dt;
      if(b.stage==='falling'){
        b.vy+=980*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;
        const sy=v74SurfaceYAt(b.x+b.w/2,b.y);
        if(b.y+b.h>=sy){b.y=sy-b.h;b.vx=0;b.vy=0;b.stage='impact';b.t=0;b._v120Captured=[];v74PlayThud();}
      }else if(b.stage==='impact'){
        if(b.t>=.16){b.stage='pull';b.t=0;b._v120Captured=b._v120Captured||[];}
      }else if(b.stage==='pull'){
        v120CollectVisibleHostiles(b);
        for(const c of (b._v120Captured||[]))v120MoveCaptureTowardBomb(b,c,dt);
        if(b.t>=3.2){
          // Snap everybody to the center for the final beat before resolution.
          for(const c of (b._v120Captured||[])){c.pinned=true;v120MoveCaptureTowardBomb(b,c,1);}
          v120ExplodeGravityBomb(b);
          b.stage='explode';b.t=0;playAudioSafe(V74_DR_T_EXPLODE);
        }
      }else if(b.stage==='explode'){
        if(b.t>=.70){b.done=true;arr.splice(i,1);}
      }
    }
  };

  // Office Hours Dr. T boss: exactly five seconds airborne, then five seconds
  // landed.  The normal side-boss shot timer is left intact, so his F power
  // continues to fire in BOTH phases.
  const V120_PREV_BUILD_WORLD=buildWorld;
  buildWorld=function(){
    const r=V120_PREV_BUILD_WORLD();
    const d=STATE.levelKey==='office'&&STATE.sideBoss&&STATE.sideBoss.row===46?STATE.sideBoss:null;
    if(d){
      d._v120LandY=Number.isFinite(d.groundY)?d.groundY:d.y;
      d._v120FlightClock=0;
      d._v120FlightStarted=false;
      d._drTBossFlying=false;
      d.groundY=d._v120LandY;
    }
    return r;
  };
  function v120UpdateOfficeDrTBoss(dt,newShotStart){
    const d=STATE.levelKey==='office'&&STATE.sideBoss&&STATE.sideBoss.row===46?STATE.sideBoss:null;
    if(!d)return;
    if(!Number.isFinite(d._v120LandY))d._v120LandY=Number.isFinite(d.groundY)?d.groundY:d.y;
    const landY=d._v120LandY;
    d.groundY=landY; // undo the old v116 airborne groundY corruption every frame
    if(!d.active||d.defeated||d.dropping){d._drTBossFlying=false;return;}
    if(!d._v120FlightStarted){d._v120FlightStarted=true;d._v120FlightClock=0;}
    d._v120FlightClock=((d._v120FlightClock||0)+Math.max(0,dt||0))%10;
    const flying=d._v120FlightClock<5;
    d._drTBossFlying=flying;
    const p=STATE.player;
    const left=Math.max(30,STATE.worldW-1050),right=Math.max(left+80,STATE.worldW-430);
    if(flying){
      const targetX=p?clamp(p.x+(p.x<d.x?190:-190),left,right):(left+right)/2;
      d.x+=clamp(targetX-d.x,-185*dt,185*dt);
      const targetY=clamp(landY-175+Math.sin((STATE.time||0)*2.1)*24,72,Math.max(80,landY-92));
      d.y+=clamp(targetY-d.y,-205*dt,205*dt);
      d.vy=0;
    }else{
      d.y=landY;d.vy=0;
      // He can reposition on the floor but is genuinely landed for the full five seconds.
      if(p){const targetX=clamp(p.x+(p.x<d.x?165:-165),left,right);d.x+=clamp(targetX-d.x,-105*dt,105*dt);}
    }
    d.groundY=landY;
    // The legacy side-boss loop fires before the final airborne position is
    // restored. Move any newly-created Dr. T F shot to the real sprite position.
    for(let i=Math.max(0,newShotStart||0);i<(STATE.bossFireballs||[]).length;i++){
      const q=STATE.bossFireballs[i];
      if(!q||!q.fromSideBoss||Number(q.row)!==46)continue;
      const dir=d.facing||1;
      q.x=d.x+(dir===-1?d.w*.18:d.w*.82);
      q.y=d.y+d.h*.48;
    }
  }

  const V120_PREV_STEP=step;
  step=function(dt){
    const shotStart=(STATE.bossFireballs||[]).length;
    V120_PREV_STEP(dt);
    v120UpdateOfficeDrTBoss(dt,shotStart);
    // This is deliberately last: platform support, boss motion, and other old
    // wrappers are not allowed to pull gravity-bomb victims away from the box.
    v120PinGravityCaptures();
  };

  window.__V120_READY__=true;
