  // height changes, but the floor/base width never changes.
  const V138_PREV_VENT_DIMS=v129VentDrawDims;
  v129VentDrawDims=function(vent,frame){
    const rest=V138_PREV_VENT_DIMS(vent,0);
    const baseW=rest.w;
    const baseH=rest.h;
    if(frame===0||frame===1||frame===15)return {w:baseW,h:baseH};
    const plumeScale={
      2:.70,3:1.05,4:1.55,5:2.05,6:2.55,7:3.00,8:3.35,
      9:3.55,10:3.45,11:3.10,12:2.45,13:1.75,14:1.10
    }[frame]||1.2;
    return {w:baseW,h:Math.max(baseH,baseW*plumeScale)};
  };

  function v138CandyColor(i){
    return ['#ef3340','#ffd529','#30c85a','#2b8df0','#8b4bdc','#ff7a27','#19c5cf','#f044a5'][Math.abs(i)%8];
  }
  function v138Rand(n){
    const x=Math.sin(n*12.9898+78.233)*43758.5453;
    return x-Math.floor(x);
  }
  function v138FrameEnergy(frame){
    if(frame<2||frame>14)return 0;
    if(frame<=8)return clamp((frame-1)/7,0,1);
    if(frame<=10)return 1;
    return clamp(1-(frame-10)/5,0,1);
  }
  function v138DrawManualGobstoppers(vent,st,sx,by,rest){
    if(st.phase!=='erupt'||st.frame<2||st.frame>14)return;
    const energy=v138FrameEnergy(st.frame);
    if(energy<=0)return;
    const plumeH=rest.w*(.62+3.05*energy);
    const coreHalf=rest.w*.34;
    const count=Math.round(10+31*energy);
    const cycle=st.cycle||0;

    ctx.save();

    // Narrow soda/steam core: never wider than the grate itself.
    const grad=ctx.createLinearGradient(sx,by-rest.h*.55,sx,by-plumeH);
    grad.addColorStop(0,'rgba(255,245,235,.76)');
    grad.addColorStop(.42,'rgba(255,214,238,.44)');
    grad.addColorStop(1,'rgba(255,255,255,.08)');
    ctx.fillStyle=grad;
    ctx.beginPath();
    ctx.moveTo(sx-coreHalf*.72,by-rest.h*.40);
    ctx.bezierCurveTo(sx-coreHalf,by-plumeH*.45,sx-coreHalf*.58,by-plumeH*.86,sx-coreHalf*.20,by-plumeH);
    ctx.bezierCurveTo(sx+coreHalf*.58,by-plumeH*.86,sx+coreHalf,by-plumeH*.45,sx+coreHalf*.72,by-rest.h*.40);
    ctx.closePath();
    ctx.fill();

    // Main Gobstopper column. Most candies remain inside the grate width.
    for(let i=0;i<count;i++){
      const seed=vent.x*.017+cycle*19.3+i*3.771;
      const yFrac=.06+v138Rand(seed+7.1)*.92;
      const columnT=1-Math.abs(yFrac-.52)*.55;
      const xNorm=(v138Rand(seed+13.4)-.5)*2;
      const px=sx+xNorm*coreHalf*columnT;
      const py=by-rest.h*.55-yFrac*plumeH;
      const r=2.4+v138Rand(seed+29.2)*3.1;
      ctx.fillStyle=v138CandyColor(i+Math.floor(vent.x/53));
      ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='rgba(255,255,255,.76)';
      ctx.beginPath();ctx.arc(px-r*.28,py-r*.30,Math.max(.7,r*.28),0,Math.PI*2);ctx.fill();
    }

    // A smaller number spray outward near the top, giving it a fountain feel
    // without widening the base/floor beneath the grate.
    const sprayCount=Math.round(3+12*energy);
    for(let i=0;i<sprayCount;i++){
      const seed=vent.x*.031+cycle*31.7+i*5.221;
      const side=v138Rand(seed+2)>.5?1:-1;
      const spread=rest.w*(.42+v138Rand(seed+3)*.82)*energy;
      const height=plumeH*(.42+v138Rand(seed+4)*.52);
      const px=sx+side*spread;
      const py=by-rest.h*.58-height;
      const r=2.1+v138Rand(seed+5)*2.7;
      ctx.strokeStyle='rgba(255,255,255,.40)';
      ctx.lineWidth=1.2;
      ctx.beginPath();ctx.moveTo(px-side*(7+4*energy),py+8);ctx.lineTo(px-side*2,py+2);ctx.stroke();
      ctx.fillStyle=v138CandyColor(i+cycle+3);
      ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='rgba(255,255,255,.72)';
      ctx.beginPath();ctx.arc(px-r*.27,py-r*.28,Math.max(.65,r*.26),0,Math.PI*2);ctx.fill();
    }

    ctx.restore();
  }

  // Authoritative Wonka renderer: frame 0 = resting grate, frame 1 = shaking
  // grate. Frames 2+ are no longer drawn at all; the Gobstoppers are rendered
  // manually above the same fixed-size grate.
  v135DrawWonkaVentsBackground=function(){
    const env=STATE.environment;
    if(!env||env.key!=='wonka')return;
    if(!env.gobstopperVents||!Array.isArray(env.gobstopperVents.vents)||!env.gobstopperVents.vents.length){
      v132EnsureWonkaVents();
    }
    const vents=env.gobstopperVents?.vents||[];
    const groundBase=(STATE.groundY||groundY)+22;
    for(const vent of vents){
      vent.supportPlatform=null;
      vent.baseY=groundBase;
      const st=v129VentState(env,vent);
      vent._v129State=st;
      const rest=v129VentDrawDims(vent,0);
      const frameIndex=st.phase==='shake'?1:0;
      const grateImg=V129_GOBSTOPPER_FRAMES[frameIndex]||V129_GOBSTOPPER_FRAMES[0];
      const shakeX=st.phase==='shake'?(st.jitterX||0):0;
      const sx=vent.x-(STATE.cameraX||0)+shakeX;
      const by=groundBase;
      const maxReach=rest.w*1.65;
      if(sx+maxReach<-50||sx-maxReach>canvas.width+50)continue;

      ctx.save();
      if(st.phase==='shake'){
        const pulse=.13+.09*Math.sin((env.elapsed||0)*24);
        ctx.fillStyle=`rgba(255,220,95,${pulse})`;
        ctx.beginPath();ctx.ellipse(sx,by-rest.h*.13,rest.w*.46,Math.max(3,rest.h*.16),0,0,Math.PI*2);ctx.fill();
      }

      v138DrawManualGobstoppers(vent,st,sx,by,rest);

      // Fixed footprint: the resting/shaking grate is always exactly this size.
      if(grateImg&&grateImg.complete&&grateImg.naturalWidth){
        ctx.shadowBlur=0;
        ctx.drawImage(grateImg,sx-rest.w/2,by-rest.h,rest.w,rest.h);
      }
      ctx.restore();
    }
  };

  window.__V138_READY__=true;
  // ========================================================================
  // end v138
  // ========================================================================


  // ========================================================================
  // v139 — falling Gobstoppers + thicker yellow curb + lollipop floor trim
  // ========================================================================

  const V139_PREV_DRAW_GROUND = drawThemedGround;
  drawThemedGround = function(){
    if(STATE.levelKey!=='wonka') return V139_PREV_DRAW_GROUND();
    const y=STATE.groundY, h=canvas.height-y;
    ctx.save();
    const g=ctx.createLinearGradient(0,y,0,canvas.height);
    g.addColorStop(0,'#ff8fd8');
    g.addColorStop(.38,'#d96bd1');
    g.addColorStop(1,'#7b3b77');
    ctx.fillStyle=g;
    ctx.fillRect(0,y,canvas.width,h);

    // Extend the pale-yellow candy curb by 10 px so it reads more clearly.
    ctx.fillStyle='#fff0a8';
    ctx.fillRect(0,y,canvas.width,20);
    ctx.fillStyle='#ff5da8';
    ctx.fillRect(0,y+20,canvas.width,7);

    // Replace the lower diagonal rectangles with repeating lollipop emoji.
    ctx.font='28px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
    ctx.textAlign='center';
    ctx.textBaseline='middle';
    for(let x=20;x<canvas.width+40;x+=84){
      ctx.fillText('🍭',x,y+40);
    }
    // Keep a few candy dots between the emoji so the strip still feels busy.
    for(let x=58;x<canvas.width+20;x+=84){
      ctx.fillStyle=(Math.floor(x/84)%2===0?'#8bf08a':'#ff6969');
      ctx.beginPath();
      ctx.arc(x,y+44,8.5,0,Math.PI*2);
      ctx.fill();
    }
    ctx.restore();
  };

  function v139GobCandyColor(i){
    return ['#ef3340','#ffd529','#30c85a','#2b8df0','#8b4bdc','#ff7a27','#19c5cf','#f044a5'][Math.abs(i)%8];
  }
  function v139GobRand(n){
    const x=Math.sin(n*12.9898+78.233)*43758.5453;
    return x-Math.floor(x);
  }
  function v139EaseOut(t){
    return 1-Math.pow(1-clamp(t,0,1),1.65);
  }

  // Replaces the retracting candy column with a simple fountain arc: rise up,
  // then fall back down to the ground around the grate.
  v138DrawManualGobstoppers = function(vent,st,sx,by,rest){
    if(st.phase!=='erupt'||st.frame<2||st.frame>14) return;
    const cycle=st.cycle||0;
    const prog=clamp((st.frame-2)/12,0,1);
    const riseCut=.54;
    const sprayProg=prog<riseCut?prog/riseCut:1;
    const fallProg=prog<=riseCut?0:(prog-riseCut)/(1-riseCut);
    const density=(prog<riseCut)
      ? (.55+.45*Math.sin((prog/riseCut)*Math.PI*.5))
      : (.85-.20*fallProg);
    const count=Math.max(14,Math.round(18+30*density));
    const mouthY=by-rest.h*.54;

    ctx.save();

    // Soda/steam core fades out instead of retracting upward.
    const coreAlpha=Math.max(0,.72-fallProg*.95);
    if(coreAlpha>.02){
      const plumeH=rest.w*(1.15+2.7*sprayProg);
      const coreHalf=rest.w*(.22+.09*sprayProg);
      const grad=ctx.createLinearGradient(sx,mouthY,sx,mouthY-plumeH);
      grad.addColorStop(0,`rgba(255,245,235,${(.54*coreAlpha).toFixed(3)})`);
      grad.addColorStop(.48,`rgba(255,214,238,${(.28*coreAlpha).toFixed(3)})`);
      grad.addColorStop(1,`rgba(255,255,255,${(.04*coreAlpha).toFixed(3)})`);
      ctx.fillStyle=grad;
      ctx.beginPath();
      ctx.moveTo(sx-coreHalf*.72,mouthY+2);
      ctx.bezierCurveTo(sx-coreHalf,mouthY-plumeH*.30,sx-coreHalf*.55,mouthY-plumeH*.86,sx-coreHalf*.14,mouthY-plumeH);
      ctx.bezierCurveTo(sx+coreHalf*.55,mouthY-plumeH*.86,sx+coreHalf,mouthY-plumeH*.30,sx+coreHalf*.72,mouthY+2);
      ctx.closePath();
      ctx.fill();
    }

    for(let i=0;i<count;i++){
      const seed=vent.x*.017 + cycle*23.17 + i*3.771;
      const side=v139GobRand(seed+3)>.5?1:-1;
      const nearCore=v139GobRand(seed+5)<.72;
      const launchSpread=nearCore?rest.w*.28:rest.w*(.16+.18*v139GobRand(seed+7));
      const launchX=sx + (v139GobRand(seed+9)-.5)*2*launchSpread;
      const peakHeight=rest.w*(1.3 + 2.25*v139GobRand(seed+11));
      const peakY=mouthY - peakHeight;
      const landingSpread=nearCore ? rest.w*(.55+.45*v139GobRand(seed+13)) : rest.w*(.95+1.05*v139GobRand(seed+15));
      const landingX=sx + side*landingSpread*(.35+.65*v139GobRand(seed+17));
      let px, py;
      if(prog<=riseCut){
        const u=prog/riseCut;
        px=launchX + (landingX-launchX)*(u*.16);
        py=mouthY - peakHeight*v139EaseOut(u);
      }else{
        const u=fallProg;
        px=launchX + (landingX-launchX)*(0.16 + 0.84*u);
        py=peakY + ((by-2)-peakY)*(u*u);
      }
      const r=2.2 + v139GobRand(seed+21)*3.1;
      if(prog<=riseCut){
        const u=prog/riseCut;
        if(u>.10){
          const tail=4 + 7*u*(.45+v139GobRand(seed+23));
          ctx.strokeStyle='rgba(255,255,255,.34)';
          ctx.lineWidth=Math.max(1,r*.36);
          ctx.beginPath();
          ctx.moveTo(px,py+tail);
          ctx.lineTo(px,py+r*.55);
          ctx.stroke();
        }
      }else if(fallProg>.05){
        const tail=5 + 8*fallProg*(.35+v139GobRand(seed+25));
        ctx.strokeStyle='rgba(255,255,255,.22)';
        ctx.lineWidth=Math.max(1,r*.34);
        ctx.beginPath();
        ctx.moveTo(px-side*(3+6*fallProg),py-tail*.35);
        ctx.lineTo(px,py-r*.2);
        ctx.stroke();
      }
      ctx.fillStyle=v139GobCandyColor(i+Math.floor(vent.x/53));
      ctx.beginPath();
      ctx.arc(px,py,r,0,Math.PI*2);
      ctx.fill();
      ctx.fillStyle='rgba(255,255,255,.76)';
      ctx.beginPath();
      ctx.arc(px-r*.28,py-r*.30,Math.max(.7,r*.28),0,Math.PI*2);
      ctx.fill();
    }

    // A few candies already on the ground during the late descent helps sell
    // the idea that they landed instead of retracting back into the vent.
    if(fallProg>.22){
      const landed=Math.round(4+8*fallProg);
      for(let i=0;i<landed;i++){
        const seed=vent.x*.049 + cycle*13.1 + i*4.03;
        const side=v139GobRand(seed+1)>.5?1:-1;
        const gx=sx + side*rest.w*(.22 + 1.08*v139GobRand(seed+2));
        const gy=by - 3 + Math.sin(seed)*1.2;
        const r=2.4 + v139GobRand(seed+3)*2.8;
        ctx.fillStyle=v139GobCandyColor(i+cycle+5);
        ctx.beginPath(); ctx.arc(gx,gy,r,0,Math.PI*2); ctx.fill();
        ctx.fillStyle='rgba(255,255,255,.72)';
        ctx.beginPath(); ctx.arc(gx-r*.27,gy-r*.28,Math.max(.6,r*.25),0,Math.PI*2); ctx.fill();
      }
    }

    ctx.restore();
  };

  window.__V139_READY__ = true;
  // ========================================================================
  // end v139
  // ========================================================================


