  const V140_CFB_BG_SRCS=[__CTEAM_ASSETS["assets/bf23c339eb546fce6ec4.png"],__CTEAM_ASSETS["assets/35935f7c784bd9407d9e.png"],__CTEAM_ASSETS["assets/351cc3ac659742dae377.png"]];
