  // --- 4 x 6 level-select grid ---------------------------------------------
  const V140_PREV_LEVEL_LAYOUT=v105EnsureLevelLayout;
  v105EnsureLevelLayout=function(){
    V140_PREV_LEVEL_LAYOUT();
    if(!levelGrid)return;
    levelGrid.style.gridTemplateColumns='repeat(4,minmax(0,1fr))';
    levelGrid.style.gridTemplateRows='repeat(6,minmax(0,1fr))';
    levelGrid.style.gap='6px';
    const panel=levelOverlay?.querySelector('.panel');if(panel)panel.style.height='min(800px,97vh)';
    const sub=panel?.firstElementChild?.querySelector('div > div:nth-child(2)');if(sub)sub.textContent='22 WORLDS • 4 × 6 GRID • ARROWS / WASD / MOUSE TO MOVE • ENTER / CLICK TO FIGHT';
  };
