      let hit=false;
      const p1=STATE.player;
      if(p1&&rectsOverlap(s,{x:p1.x,y:p1.y,w:p1.w,h:p1.h})){hurtPlayer(s.x+s.w/2);hit=true;}
      const p2=STATE.player2;
