  function v147BuildPanorama(key, img){
    if(!img || !img.complete || !img.naturalWidth || !img.naturalHeight) return null;
    const sig = `${img.src}|${img.naturalWidth}x${img.naturalHeight}`;
    const cached = V147_BG_CACHE[key];
    if(cached && cached.sig === sig) return cached.canvas;

    const panels = 3;
    const w = img.naturalWidth;
    const h = img.naturalHeight;
    const c = document.createElement('canvas');
    c.width = w * panels;
    c.height = h;
    const cctx = c.getContext('2d');

    for(let i=0;i<panels;i++){
      const panelX = i*w;
      cctx.save();
      let filter = 'none';
      if(key === 'space' && i === 0){
        filter = 'grayscale(1) contrast(1.02)';
      } else if(i === 1) {
        filter = 'saturate(1.03) brightness(1.02)';
      } else if(i === 2) {
        filter = 'saturate(1.07) brightness(1.03)';
      }
      cctx.filter = filter;
      if(i % 2 === 1){
        cctx.translate(panelX + w, 0);
        cctx.scale(-1, 1);
        cctx.drawImage(img, 0, 0, w, h);
      } else {
        cctx.drawImage(img, panelX, 0, w, h);
      }
      cctx.restore();

      // Gentle tinting so each panel feels a little more like an extension than
      // a perfect copy.
      cctx.save();
      cctx.globalAlpha = 0.12;
      if(key === 'space' && i === 0){
        cctx.fillStyle = 'rgba(240,240,240,0.65)';
      } else if(key === 'wonka'){
        cctx.fillStyle = ['rgba(255,215,230,0.22)','rgba(255,245,190,0.18)','rgba(215,255,235,0.18)'][i];
      } else {
        cctx.fillStyle = ['rgba(255,255,255,0.10)','rgba(255,255,255,0.04)','rgba(0,0,0,0.05)'][i];
      }
      cctx.fillRect(panelX,0,w,h);
      cctx.restore();

      v147DrawThemeExtras(cctx,key,panelX,w,h,i);
    }

    // Blend the seams.
    for(let i=1;i<panels;i++){
      const seam = i*w;
      cctx.save();
      const g = cctx.createLinearGradient(seam-26,0,seam+26,0);
      g.addColorStop(0,'rgba(255,255,255,0)');
      g.addColorStop(0.5,'rgba(255,255,255,0.22)');
      g.addColorStop(1,'rgba(255,255,255,0)');
      cctx.fillStyle = g;
      cctx.fillRect(seam-26,0,52,h);
      cctx.restore();
    }

    V147_BG_CACHE[key] = { sig, canvas:c };
    return c;
  }

  const V147_PREV_DRAW_BACKGROUND = drawBackground;
  drawBackground = function(){
    const key = (STATE && STATE.levelKey) || 'goomba';
    if(!v147IsHorizontalLevel(key)) return V147_PREV_DRAW_BACKGROUND();

    const baseImg = (typeof LEVEL_BG_IMAGES !== 'undefined' && LEVEL_BG_IMAGES[key]) ? LEVEL_BG_IMAGES[key] : getCurrentLevelBgImage();
    const pano = v147BuildPanorama(key, baseImg);
    if(!pano || !pano.width || !pano.height) return V147_PREV_DRAW_BACKGROUND();

    const srcW = pano.width;
    const srcH = pano.height;
    const scale = Math.max(canvas.width / srcW, canvas.height / srcH);
    const drawW = srcW * scale;
    const drawH = srcH * scale;
    const extraX = Math.max(0, drawW - canvas.width);
    const denom = Math.max(1, STATE.worldW - canvas.width);
    const progress = Math.min(1, Math.max(0, STATE.cameraX / denom));
    const x = -extraX * progress;
    const y = (canvas.height - drawH) / 2;
    ctx.drawImage(pano, x, y, drawW, drawH);

    ctx.save();
    const wash = ctx.createLinearGradient(0,0,0,canvas.height);
    wash.addColorStop(0,'rgba(255,255,255,0.08)');
    wash.addColorStop(1,'rgba(11,16,32,0.10)');
    ctx.fillStyle = wash;
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // A visual marker for the Wizard of Oz style transition.
    if(key === 'space'){
      const boundaryWorldX = (STATE.worldW || canvas.width) / 3;
      const boundaryScreenX = boundaryWorldX - (STATE.cameraX || 0);
      if(boundaryScreenX > -40 && boundaryScreenX < canvas.width + 40){
        const g = ctx.createLinearGradient(boundaryScreenX-14,0,boundaryScreenX+14,0);
        g.addColorStop(0,'rgba(255,255,255,0)');
        g.addColorStop(0.5,'rgba(255,255,255,0.6)');
        g.addColorStop(1,'rgba(255,255,255,0)');
        ctx.fillStyle = g;
        ctx.fillRect(boundaryScreenX-14,0,28,canvas.height);
      }
    }
    ctx.restore();

    if (STATE.levelKey === 'mountain' && STATE.environment && STATE.environment.eraser) {
      const env = STATE.environment;
      const e = env.eraser;
      let bgAlpha = 0;
      if (e.active) {
        bgAlpha = 0.98;
      } else if (e.bgEraseUntil && env.elapsed < e.bgEraseUntil) {
        bgAlpha = clamp((e.bgEraseUntil - env.elapsed) / 2.6, 0, 1) * 0.96;
      }
      if (bgAlpha > 0) {
        const wipeX = ((e.bgEraseX != null) ? e.bgEraseX : e.targetX) - STATE.cameraX;
        const wipeW = e.w + 18;
        if (wipeX + wipeW/2 > -140 && wipeX - wipeW/2 < canvas.width + 140) {
          ctx.save();
          ctx.globalAlpha = bgAlpha;
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(wipeX - wipeW/2, 0, wipeW, canvas.height);
          ctx.restore();
        }
      }
    }
  };

