    const now=STATE.time||0;
    const p1=STATE.player,p2=STATE.player2;
    const p1y=p1?.y,p2y=p2?.y;
    const ralphStat=V97_CHARACTER_STATS[V148_RALPH_ROW];
    const buffed=!!((p1&&STATE.selectedHorseRow===V148_RALPH_ROW&&(p1.ralphGlueT||0)>0)||(p2&&STATE.selectedHorseRow2===V148_RALPH_ROW&&(p2.ralphGlueT||0)>0));
