    const bs=v148FreezeBossSnapshot(STATE.boss),ss=v148FreezeBossSnapshot(STATE.sideBoss);
    const r=V148_PREV_STEP(dt);
    if(ralphStat){ralphStat.speed=2;ralphStat.jump=2;}
    v148RestoreBossSnapshot(STATE.boss,bs);v148RestoreBossSnapshot(STATE.sideBoss,ss);

    if(p1)p1.ralphGlueT=Math.max(0,(p1.ralphGlueT||0)-dt);
    if(p2)p2.ralphGlueT=Math.max(0,(p2.ralphGlueT||0)-dt);

