  const V151_PREV_BG=drawBackground;
  drawBackground=function(){
    if(STATE.levelKey!=='evergreen')return V151_PREV_BG();
    const img=V149_EVERGREEN_IMG;
    if(!(img&&img.complete&&img.naturalWidth))return V151_PREV_BG();

    const panoW=V149_WORLD_W;
    const worldTravel=Math.max(1,V151_EVERGREEN_WORLD_W-canvas.width);
    const panoTravel=Math.max(0,panoW-canvas.width);
    const camera=clamp(STATE.cameraX||0,0,worldTravel);
    const panoX=panoTravel*(camera/worldTravel);

    ctx.save();
    ctx.imageSmoothingEnabled=true;
    ctx.drawImage(img,-panoX,0,panoW,canvas.height);
    const wash=ctx.createLinearGradient(0,0,0,canvas.height);
    wash.addColorStop(0,'rgba(255,255,255,.018)');
    wash.addColorStop(1,'rgba(12,20,34,.035)');
    ctx.fillStyle=wash;
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.restore();
  };

