  function v153DrawTupperwareBoss(){
    const t=STATE.coonTupperwareBoss;
    if(!t||!t.active||t.defeated)return;
    const sx=t.x-(STATE.cameraX||0),cy=t.y+t.h*.5;
    if(sx<-140||sx>canvas.width+140)return;
    ctx.save();
    if(t.bubbleActive){
      const pulse=1+Math.sin((t.bubblePhase||0)*8)*.035;
      const r=Math.max(t.w,t.h)*.72*pulse;
      const g=ctx.createRadialGradient(sx+t.w*.5,cy,r*.15,sx+t.w*.5,cy,r);
      g.addColorStop(0,'rgba(220,250,255,.10)');g.addColorStop(.72,'rgba(110,205,255,.16)');g.addColorStop(1,'rgba(70,160,255,.30)');
      ctx.fillStyle=g;ctx.strokeStyle='rgba(205,245,255,.92)';ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(sx+t.w*.5,cy,r,0,Math.PI*2);ctx.fill();ctx.stroke();
    }
    const frames=V142_TUPPERWARE_WALK||[];
    const img=frames.length?frames[Math.floor((t.animT||0)*8.6)%frames.length]:null;
    if(img&&img.complete&&img.naturalWidth){
      const drawH=80,drawW=drawH*(img.naturalWidth/Math.max(1,img.naturalHeight));
      const pivot=sx+t.w*.5;
      if((t.facing||1)<0){ctx.translate(pivot,0);ctx.scale(-1,1);ctx.translate(-pivot,0);}
      ctx.drawImage(img,pivot-drawW/2,t.y+t.h-drawH,drawW,drawH);
    }
    ctx.restore();

    ctx.save();
    ctx.textAlign='center';ctx.textBaseline='bottom';
    ctx.font='900 13px system-ui';ctx.fillStyle='white';ctx.strokeStyle='rgba(0,0,0,.8)';ctx.lineWidth=4;
    ctx.strokeText(`Tupperware ${t.hp}/${t.maxHp}`,sx+t.w*.5,t.y-8);ctx.fillText(`Tupperware ${t.hp}/${t.maxHp}`,sx+t.w*.5,t.y-8);
    ctx.restore();
  }

