  v149ActivateRalphGlue=function(p){
    if(!p)return false;
    const now=STATE.time||0,end=now+7.0;
    const targets=v149AllHostiles().filter(v149IsOnScreen);
    STATE._v149GlueTargets=new Set(targets);
    STATE._v149GlueStart=now;
    STATE._v149GlueBurst={start:now,x:p.x+p.w/2,groundY:STATE.groundY,_v155Crayon:true};
    STATE.ralphGlueUntil=end;
    p.ralphGlueT=7.0;
    p.specialAbilitySerial=(p.specialAbilitySerial||0)+1;
    p.fireAnimT=1.15;
    for(const e of targets){
      e._v149GlueStart=now;
      v148GlueTarget(e,end);
      if(Number.isFinite(e._ralphGluePinX))e.x=e._ralphGluePinX;
      if(Number.isFinite(e._ralphGluePinY))e.y=e._ralphGluePinY;
      if('vx' in e)e.vx=0;if('vy' in e)e.vy=0;
    }
    v149PlayRalphF();
    return true;
  };

  const V155_CRAYON_COLORS=['#e53935','#1e88e5','#43a047','#fdd835','#8e24aa','#fb8c00','#00acc1'];
  function v155DrawCrayon(x,y,len,ang,color,alpha=1){
    ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.rotate(ang);
    ctx.fillStyle=color;ctx.strokeStyle='rgba(25,25,25,.8)';ctx.lineWidth=1.5;
    ctx.fillRect(-len*.5,-4,len,8);ctx.strokeRect(-len*.5,-4,len,8);
    ctx.fillStyle='#f4d6b8';ctx.beginPath();ctx.moveTo(len*.5, -4);ctx.lineTo(len*.5+8,0);ctx.lineTo(len*.5,4);ctx.closePath();ctx.fill();
    ctx.restore();
  }
  v149DrawGlueBurst=function(){
    const b=STATE._v149GlueBurst;if(!b)return;
    const age=(STATE.time||0)-b.start;
    if(age<0||age>.82){if(age>.82)STATE._v149GlueBurst=null;return;}
    const p=clamp(age/.68,0,1),ease=1-Math.pow(1-p,3);
    const origin=b.x-(STATE.cameraX||0),radius=(canvas.width+180)*ease;
    for(let i=0;i<22;i++){
      const q=i/21,x=origin-radius+radius*2*q;
      if(x<-40||x>canvas.width+40)continue;
      const color=V155_CRAYON_COLORS[i%V155_CRAYON_COLORS.length];
      v155DrawCrayon(x,STATE.groundY-8-(i%3)*5,24+(i%4)*3,(i%2?-.25:.25),color,.92*(1-age/.95));
    }
  };
  v149DrawGlueTarget=function(e){
    if(!e||!(e._ralphGlueUntil>(STATE.time||0)))return;
    const now=STATE.time||0,start=Number.isFinite(e._v149GlueStart)?e._v149GlueStart:(STATE._v149GlueStart||now);
    let b;try{b=basicEnemyBox(e);}catch(_e){b={x:e.x||0,y:e.y||0,w:e.w||64,h:e.h||64};}
    const cx=b.x-(STATE.cameraX||0)+b.w/2,cy=b.y+b.h*.53,rx=Math.max(34,b.w*.72),ry=Math.max(42,b.h*.60);
    if(cx<-150||cx>canvas.width+150)return;
    ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
    for(let k=0;k<3;k++){
      ctx.strokeStyle=V155_CRAYON_COLORS[(k+Math.floor(start*10))%V155_CRAYON_COLORS.length];
      ctx.globalAlpha=.74;ctx.lineWidth=4;
      ctx.beginPath();
      const pts=18;
      for(let i=0;i<=pts;i++){
        const a=(i/pts)*Math.PI*2 + k*.7 + now*1.3;
        const wob=1+Math.sin(i*2.7+now*5+k)*.12;
        const x=cx+Math.cos(a)*rx*wob,y=cy+Math.sin(a)*ry*wob;
        if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
      }
      ctx.stroke();
    }
    ctx.restore();
    for(let i=0;i<8;i++){
      const a=i/8*Math.PI*2, color=V155_CRAYON_COLORS[i%V155_CRAYON_COLORS.length];
      v155DrawCrayon(cx+Math.cos(a)*rx*.9,b.y+b.h-6+Math.sin(a)*7,22,a+.35,color,.96);
    }
  };

  // Willie playable F: startup animation then 8 full seconds of leaf-blower
  // cycling. Only enemies within 2-star reach in front of the nozzle are caught.
  const V155_WILLIE_START_SECONDS=.82, V155_WILLIE_LOOP_SECONDS=8.0;
  function v155WillieCapturable(e){
    if(!e||e===STATE.boss||e===STATE.sideBoss||e===STATE.evergreenCatBoss||e===STATE.coonTupperwareBoss)return false;
    return e.alive!==false&&e.active!==false&&e.defeated!==true;
  }
  function v155WillieReachTargets(p){
    const out=[],seen=new Set(),dir=(p.facing||1)>=0?1:-1;
    const px=p.x+p.w*.5,py=p.y+p.h*.5,reach=canvas.width*.25;
    for(const e of v149AllHostiles()){
      if(!v155WillieCapturable(e)||seen.has(e))continue;
      let b;try{b=basicEnemyBox(e);}catch(_e){b={x:e.x||0,y:e.y||0,w:e.w||60,h:e.h||70};}
      const ex=b.x+b.w*.5,ey=b.y+b.h*.5,dx=(ex-px)*dir,dy=Math.abs(ey-py);
      if(dx>=-15&&dx<=reach&&dy<=175){seen.add(e);out.push(e);}
    }
    return out;
  }
  function v155ActivateWillie(p){
    if(!p)return false;
    const now=STATE.time||0,total=V155_WILLIE_START_SECONDS+V155_WILLIE_LOOP_SECONDS;
    p.willieLeafStart=now;p.willieLeafT=total;p.specialAbilitySerial=(p.specialAbilitySerial||0)+1;p.fireAnimT=total;
    const targets=v155WillieReachTargets(p);
    p._v155WillieTargets=targets;
    targets.forEach((e,i)=>{
      e._willieHeldBy=p;e._willieHoldIndex=i;e._willieHoldUntil=now+total;e._willieFalling=false;
      e._customFreezeUntil=now+total;e._customFreezeX=e.x;e._customFreezeY=e.y;
      if('vx' in e)e.vx=0;if('vy' in e)e.vy=0;
    });
    try{SFX.fire();}catch(_e){}
    return true;
  }
  function v155KillEntity(e){
    if(!e)return;
    if('alive' in e)e.alive=false;if('active' in e)e.active=false;
    if('defeated' in e&&e!==STATE.boss&&e!==STATE.sideBoss)e.defeated=true;
    if(e===STATE.evergreenDuffman){e.active=false;e.alive=false;STATE.evergreenDuffman=null;STATE.evergreenDuffmanTimer=0;}
  }
  function v155UpdateWillieHeld(dt){
    const now=STATE.time||0;
    for(const p of [STATE.player,STATE.player2]){
      if(!p||!(p.willieLeafT>0))continue;
      const elapsed=now-(p.willieLeafStart??now),blowing=elapsed>=V155_WILLIE_START_SECONDS;
      const dir=(p.facing||1)>=0?1:-1,targets=p._v155WillieTargets||[];
      if(blowing){
        const nozzleX=p.x+p.w*.5+dir*112,nozzleY=p.y+p.h*.42;
        targets.forEach((e,i)=>{
          if(!v155WillieCapturable(e)||e._willieFalling)return;
          const stack=i%5,ring=Math.floor(i/5),a=now*8+i*1.7;
          e.x=nozzleX+dir*(18+ring*12)+Math.cos(a)*22-(e.w||60)*.5;
          e.y=nozzleY-20-stack*14+Math.sin(a)*23-(e.h||60)*.5;
          e._customFreezeX=e.x;e._customFreezeY=e.y;e._customFreezeUntil=now+.15;
          e._v155SpinAngle=a;
        });
      }
    }
    // release/fall after the blower finishes
    const all=v149AllHostiles();
    for(const e of all){
      if(!e||!e._willieHeldBy)continue;
      const owner=e._willieHeldBy;
      if((owner.willieLeafT||0)>0)continue;
      if(!e._willieFalling){
        e._willieFalling=true;e._willieFallVY=-35;e._willieFallX=e.x;
        e._willieHeldBy=null;e._customFreezeUntil=0;e._ralphGlueUntil=0;
      }
    }
    for(const e of all){
      if(!e||!e._willieFalling||e.alive===false||e.active===false)continue;
      e.x=e._willieFallX;e._willieFallVY=(e._willieFallVY||0)+1450*dt;e.y+=e._willieFallVY*dt;
      const h=e.h||60;
      if(e.y+h>=STATE.groundY){e.y=STATE.groundY-h;e._willieFalling=false;v155KillEntity(e);try{SFX.pop();}catch(_e){}}
    }
  }

  // Cat Lady playable F projectile.
