        const ty=clamp(feet-e.h-hover,28,STATE.groundY-e.h);
        const dx=tx-e.x,dy=ty-e.y;
        if(Math.abs(dx)>.5)e.x+=Math.sign(dx)*Math.min(Math.abs(dx),128*dt);
        if(Math.abs(dy)>.5)e.y+=Math.sign(dy)*Math.min(Math.abs(dy),66*dt);
