      const s=shots[i];s.life-=dt;s.spin=(s.spin||0)+dt*8;s.vy+=(s.g||0)*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;
      if(s.life<=0||s.x<STATE.cameraX-180||s.x>STATE.cameraX+canvas.width+180||s.y>canvas.height+100){shots.splice(i,1);continue;}
      let hit=false;
      if(STATE.player&&rectsOverlap(s,{x:STATE.player.x,y:STATE.player.y,w:STATE.player.w,h:STATE.player.h})){hurtPlayer(s.x+s.w*.5);hit=true;}
      if(!hit&&STATE.playerCount===2&&STATE.player2&&rectsOverlap(s,{x:STATE.player2.x,y:STATE.player2.y,w:STATE.player2.w,h:STATE.player2.h})){hurtPlayer2(s.x+s.w*.5);hit=true;}
