    const e=STATE.evergreenCatBoss;if(!e||!e.active||e.defeated||e.bubbleActive||(e.hitCooldown||0)>0)return false;
    e.hp=Math.max(0,e.hp-1);e.hitCooldown=.5;try{SFX.pop();}catch(_e){}
