    e.x+=e.dir*82*dt;if(e.x<=e.minX){e.x=e.minX;e.dir=1;}if(e.x>=e.maxX){e.x=e.maxX;e.dir=-1;}e.facing=e.dir;
    e.jumpT-=dt;if(e.y>=e.groundY-1&&e.jumpT<=0){e.vy=-760;e.jumpT=3.0;}e.vy+=1550*dt;e.y+=e.vy*dt;if(e.y>=e.groundY){e.y=e.groundY;e.vy=0;}
