  // Marge shield protection is made visible to the existing damage system by
  // keeping her normal invulnerability timer topped up during the 5-second ON phase.
  const V155_PREV_STEP=step;
  step=function(dt){
    const p1=STATE.player,p2=STATE.player2,p1y=p1?.y,p2y=p2?.y;
    const preBossDef=!!STATE.boss?.defeated,preSideDef=!!STATE.sideBoss?.defeated;
    if(p1&&STATE.selectedHorseRow===V155_MARGE_ROW&&v155MargeShieldActive(p1))STATE.invulnT=Math.max(STATE.invulnT||0,.25);
    if(p2&&STATE.playerCount===2&&STATE.selectedHorseRow2===V155_MARGE_ROW&&v155MargeShieldActive(p2))STATE.invulnT2=Math.max(STATE.invulnT2||0,.25);
    const out=V155_PREV_STEP(dt);

    for(const p of [STATE.player,STATE.player2]){
      if(!p)continue;
      p.willieLeafT=Math.max(0,(p.willieLeafT||0)-dt);
      p.margeShieldT=Math.max(0,(p.margeShieldT||0)-dt);
    }
    v155UpdateWillieHeld(dt);
    if(STATE.levelKey==='evergreen'){
      v155UpdateEvergreenWalkers(dt,p1y,p2y);
      v155UpdateDuffman(dt,p1y,p2y);
      v155UpdateEnemyShots(dt);
      v155MaybeSpawnCatBoss(preBossDef,preSideDef);
      v155UpdateCatBoss(dt,p1y,p2y);
    }
    return out;
  };

  // Draw Evergreen walkers using the clean per-frame crops. No orange guide
