    if(!Array.isArray(p._v155WillieTargets))p._v155WillieTargets=[];
    if(p._v155WillieTargets.includes(e))return false;
    const i=p._v155WillieTargets.length;
    p._v155WillieTargets.push(e);
    e._willieHeldBy=p;e._willieHoldIndex=i;e._willieHoldUntil=(p.willieLeafStart??now)+V155_WILLIE_START_SECONDS+V155_WILLIE_LOOP_SECONDS;
    e._willieFalling=false;e._customFreezeUntil=now+.15;e._customFreezeX=e.x;e._customFreezeY=e.y;
    if('vx' in e)e.vx=0;if('vy' in e)e.vy=0;
