  // ========================================================================
  // v159 — full roster mobile-fit select + PlayPlace display rename
  // The roster now uses 8 columns x 7 rows so all 56 characters fit fully
  // inside the 960x540 canvas with a safe bottom margin. Minion remains in
  // the game and in the roster; no character code is removed.
  // ========================================================================
  const V159_SELECT_COLS=8;
  const V159_SELECT_W=112;
  const V159_SELECT_H=43;
  const V159_SELECT_GX=4;
  const V159_SELECT_GY=2;
  const V159_SELECT_Y=184;

  function v159RosterRows(){
    // V140_SELECT_ROWS is the authoritative current roster and already
    // contains Willie, Crazy Cat Lady, Marge and Tupperware in this build.
    if(Array.isArray(V140_SELECT_ROWS)&&V140_SELECT_ROWS.length)return V140_SELECT_ROWS.slice();
    return Array.isArray(V97_SELECT_ROWS)?V97_SELECT_ROWS.slice():[];
  }

  getCharacterBoxes=function(){
    const roster=v159RosterRows();
    const cols=V159_SELECT_COLS,w=V159_SELECT_W,h=V159_SELECT_H,gx=V159_SELECT_GX,gy=V159_SELECT_GY;
    const totalW=cols*w+(cols-1)*gx;
    const normalX=Math.round((canvas.width-totalW)/2);
    const rowCount=Math.ceil(roster.length/cols);
    return roster.map((row,i)=>{
      const rr=Math.floor(i/cols),cc=i%cols;
      const count=(rr===rowCount-1)?Math.max(1,roster.length-rr*cols):cols;
      const thisW=count*w+(count-1)*gx;
      const rowX=(rr===rowCount-1&&count<cols)?Math.round((canvas.width-thisW)/2):normalX;
      const free=Array.isArray(V140_FREE_ROWS)&&V140_FREE_ROWS.includes(row);
      return{
        row,
        name:CHARACTER_NAMES[row],
        unlockReq:free?null:getUnlockRequirementForRow(row),
        locked:!isCharacterUnlocked(row),
        group:free?'starter':'level',
        x:rowX+cc*(w+gx),
        y:V159_SELECT_Y+rr*(h+gy),
        w,h
      };
    });
  };

  // Match keyboard navigation to the new 8-column roster.
  v104NextCursor=function(dx,dy){
    const boxes=getCharacterBoxes();if(!boxes.length)return;
    const cols=V159_SELECT_COLS,rows=Math.ceil(boxes.length/cols),picked=new Set(STATE.selectionRows||[]);
    let idx=clamp(v104CursorIndex|0,0,boxes.length-1),row=Math.floor(idx/cols),col=idx%cols;
    let next=idx;
    for(let tries=0;tries<boxes.length+cols;tries++){
      if(dx)col=(col+dx+cols)%cols;
      if(dy)row=(row+dy+rows)%rows;
      const candidate=row*cols+col;
      if(candidate>=boxes.length)continue;
      const b=boxes[candidate];
      if(!b||b.locked||picked.has(b.row))continue;
      next=candidate;break;
    }
    if(next!==v104CursorIndex){v104CursorIndex=next;v104PlayMoveSound();}
  };

  // Slightly tighten the art/name layout inside each smaller roster tile.
  const V159_PREV_DRAW_SELECT=drawSelect;
  drawSelect=function(){
    ctx.clearRect(0,0,canvas.width,canvas.height);v104DrawSelectBackdrop();
    const boxes=getCharacterBoxes();if(!boxes.length)return;
    v104CursorIndex=clamp(v104CursorIndex|0,0,boxes.length-1);
    v104DrawSelectHeader(boxes[v104CursorIndex].row);
    for(let i=0;i<boxes.length;i++){
      const b=boxes[i],owner=v104SelectedOwner(b.row),picked=owner>0,focused=i===v104CursorIndex;
      ctx.save();
      const baseG=ctx.createLinearGradient(b.x,b.y,b.x,b.y+b.h);
      baseG.addColorStop(0,picked?'#30343a':'#182f55');baseG.addColorStop(1,picked?'#15171a':'#0a172c');
      ctx.fillStyle=baseG;ctx.fillRect(b.x,b.y,b.w,b.h);
      ctx.strokeStyle=picked?'rgba(190,190,190,.25)':'rgba(100,149,205,.45)';ctx.lineWidth=1.25;ctx.strokeRect(b.x+.5,b.y+.5,b.w-1,b.h-1);
      if(focused&&!picked){ctx.shadowColor='rgba(255,213,40,.85)';ctx.shadowBlur=7;ctx.strokeStyle='#ffd62a';ctx.lineWidth=3;ctx.strokeRect(b.x+1.5,b.y+1.5,b.w-3,b.h-3);ctx.shadowBlur=0;}
      const name=CHARACTER_NAMES[b.row]||b.name;
      ctx.textAlign='center';ctx.textBaseline='top';ctx.fillStyle=picked?'rgba(210,210,210,.52)':'rgba(255,255,255,.94)';
      const np=v104FitText(name,b.w-6,8.8,6.1,800);ctx.font=`800 ${np}px system-ui`;ctx.fillText(name,b.x+b.w/2,b.y+1,b.w-4);
      // Keep the entire portrait inside the tile with a dedicated bottom margin.
      v104DrawCharacterArt(b.row,b.x+6,b.y+10,b.w-12,b.h-12,{alpha:picked?.55:1,grey:picked});
      if(b.locked){ctx.fillStyle='rgba(0,0,0,.55)';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#fff';ctx.font='16px system-ui';ctx.textBaseline='middle';ctx.fillText('🔒',b.x+b.w/2,b.y+b.h/2+2);}
      if(picked){ctx.fillStyle='rgba(8,10,14,.60)';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#d9dde4';ctx.font='950 10px system-ui';ctx.textBaseline='middle';ctx.fillText(`P${owner} ✓`,b.x+b.w/2,b.y+b.h/2+2);}
      ctx.restore();
    }
  };

