  const V161_PREV_STEP=step;
  step=function(dt){
    if(STATE.v161BattleActive){v161StepBattle(dt);return;}
    // Make the visible recharge bar behave like a real meter even for older
    // specials that use custom cooldown fields: pressing a ready Action/Power
    // drains the visual meter instantly, then it regenerates with time.
    const k=STATE.keys||{};
    const p1=STATE.player,p2=STATE.player2,row1=STATE.selectedHorseRow,row2=STATE.selectedHorseRow2;
    const o=!!k.o,v=!!k.v;
    if(p1&&o&&!p1._v161MeterKeyO&&!isV69ContextActionAvailable(p1,1)&&v97SpecialReady(p1,row1)){p1._v161MeterRemain=v97RechargeSeconds(row1);v129MeterUse(p1,row1);}
    if(p2&&STATE.playerCount===2&&v&&!p2._v161MeterKeyV&&!isV69ContextActionAvailable(p2,2)&&v97SpecialReady(p2,row2)){p2._v161MeterRemain=v97RechargeSeconds(row2);v129MeterUse(p2,row2);}
    if(p1)p1._v161MeterKeyO=o;if(p2)p2._v161MeterKeyV=v;
    return V161_PREV_STEP(dt);
  };
  const V161_PREV_DRAW_PLAY=drawPlay;
