      const b=STATE.v161Battle;if(scoreEl)scoreEl.textContent='P1 ❤ '+b.hp1;if(score2El)score2El.textContent=(b.humanPlayers===1?'CPU':'P2')+' ❤ '+b.hp2;if(carrotsEl)carrotsEl.style.display='none';if(coinsEl)coinsEl.style.display='none';try{v97UpdateSpecialHUD();}catch(_e){}return;
