  window.__V161_QA__={homeButtons:()=>introOverlay?.querySelectorAll('.v161HomeActions button').length||0,qsets:()=>introOverlay?.querySelectorAll('button[data-qset]').length||0,introChildren:()=>introOverlay?.children.length||0,battleDamage:[1,2,3,4,5].map(recharge=>clamp(7-recharge,2,6)),margeWalkFrames:V161_MARGE_WALK.length,margeCastFrames:V161_MARGE_CAST.length};
