    try{document.body.style.backgroundImage='linear-gradient(rgba(2,5,12,.34),rgba(2,5,12,.48)),var(--v169-c-team-bg)';document.body.style.backgroundSize='cover';document.body.style.backgroundPosition='center';document.body.style.backgroundRepeat='no-repeat';}catch(_e){}
    try{const wrap=document.getElementById('wrap');if(wrap){wrap.style.backgroundImage='linear-gradient(rgba(2,5,12,.34),rgba(2,5,12,.48)),var(--v169-c-team-bg)';wrap.style.backgroundSize='cover';wrap.style.backgroundPosition='center';wrap.style.backgroundRepeat='no-repeat';}}catch(_e){}
