    const team=side===1?b.team1:b.team2,cds=side===1?b.cooldowns1:b.cooldowns2,row=team[newIdx];
    const x=old?.x??(side===1?140:772),facing=side===1?1:-1,p=v161BattleFighter(x,row,facing);p.y=Math.min(old?.y??374,b.groundY-p.h);p._v161BattleCd=cds[newIdx]||0;p._v161BattleCdTotal=v161BattleRecharge(row);p._v163BattleSwitchHeld=false;
    if(side===1){b.active1=newIdx;b.row1=row;STATE.player=p;STATE.selectedHorseRow=row;b.hp1=b.teamHp1[newIdx];}
