    STATE.v161Battle={humanPlayers:1,team1:t1,team2:t2,teamHp1:[20,20],teamHp2:[20,20],active1:0,active2:0,cooldowns1:[0,0],cooldowns2:[0,0],row1:t1[0],row2:t2[0],hp1:20,hp2:20,key,winner:0,finished:false,effects:[],groundY:450,platforms:[{x:120,y:345,w:190,h:18},{x:385,y:285,w:190,h:18},{x:650,y:345,w:190,h:18}],deadT1:0,deadT2:0};
