    STATE.player=v161BattleFighter(140,t1[0],1);STATE.player2=v161BattleFighter(772,t2[0],-1);STATE.playerCount=2;STATE.screen='play';STATE.paused=false;STATE.cameraX=0;STATE.cameraY=0;
