    const deadKey=side===1?'deadT1':'deadT2';if((b[deadKey]||0)>0||arr[idx]<=0)return;
    arr[idx]=Math.max(0,arr[idx]-damage);if(side===1){b.hp1=arr[idx];STATE.player._v161HitFlash=.26;}else{b.hp2=arr[idx];STATE.player2._v161HitFlash=.26;}
    const p=side===1?STATE.player:STATE.player2;if(p&&Number.isFinite(sourceX)){const dir=(p.x+p.w/2<sourceX)?-1:1;p.vx=dir*235;p.vy=-230;}
