    STATE.v163Mode=null;STATE.v163NoQHP=null;STATE.v163NoQGameOver=false;STATE.v163DeathPending=false;STATE.v161BattleActive=false;STATE.v161BattleSetup=false;STATE.v161NoQuestions=false;STATE.v161Battle=null;
