    hit:()=>{STATE.invulnT=0;hurtPlayer(STATE.player?STATE.player.x+200:null);return STATE.v163NoQHP?.slice();},
    collectCarrot:()=>{if(!STATE.player||!STATE.carrots?.length)return;const c=STATE.carrots.find(x=>!x.collected);if(c){c.x=STATE.player.x;c.y=STATE.player.y;STATE.paused=false;step(.016);}return{hp:STATE.v163NoQHP?.slice(),collected:STATE.collected,score:STATE.score};},
    collectHeart:()=>{if(!STATE.player)return;STATE.hearts=STATE.hearts||[];STATE.hearts.push({x:STATE.player.x,y:STATE.player.y,w:28,h:28,collected:false,popped:true,yTarget:STATE.player.y,vy:0});STATE.paused=false;step(.016);return{hp:STATE.v163NoQHP?.slice(),score:STATE.score};},
