    let frames,idx;
    if(elapsed<V172_WILLIE_TRANSFORM_SECONDS){
      frames=V155_WILLIE_START;
      idx=Math.min(frames.length-1,Math.floor((elapsed/V172_WILLIE_TRANSFORM_SECONDS)*frames.length));
    }else{
      frames=V155_WILLIE_BLOWER;
      idx=Math.floor((elapsed-V172_WILLIE_TRANSFORM_SECONDS)*7.5)%Math.max(1,frames.length);
    }
    const img=frames[idx]||frames[0];if(!img||!img.complete||!img.naturalWidth)return;
    const dh=116,dw=dh*(img.naturalWidth/Math.max(1,img.naturalHeight));
    const cx=p.x-(STATE.cameraX||0)+p.w*.5,by=p.y+p.h+10,dir=(p.facing||1)>=0?1:-1;
    ctx.save();ctx.imageSmoothingEnabled=true;try{ctx.imageSmoothingQuality='high';}catch(_e){}
