    for(const [p,which] of [[STATE.player,1],[STATE.player2,2]]){if(!p||(which===2&&STATE.playerCount!==2))continue;const pb={x:p.x,y:p.y,w:p.w,h:p.h};if(!rectsOverlap(pb,eb))continue;const stomp=(p.vy||0)>70&&(p.y+p.h)<=e.y+e.h*.56&&!aura;if(stomp){v178HorseDefeat(e);p.y=e.y-p.h;p.vy=-420;}else{if(which===2)hurtPlayer2(e.x+e.w/2);else hurtPlayer(e.x+e.w/2);}}
