    ov.innerHTML=`<div style="width:min(470px,88vw);padding:24px 26px;border-radius:20px;background:rgba(8,16,35,.90);border:1px solid rgba(255,255,255,.18);box-shadow:0 24px 70px rgba(0,0,0,.55);backdrop-filter:blur(7px);text-align:center;color:#fff;font-family:system-ui,sans-serif;">
      <div style="font:950 29px system-ui;margin-bottom:7px;">Preparing Character Select…</div>
      <div id="v179SelectLoaderText" style="font:650 14px system-ui;opacity:.88;margin-bottom:14px;">Loading roster artwork</div>
      <div style="height:12px;border-radius:999px;background:rgba(255,255,255,.12);overflow:hidden;border:1px solid rgba(255,255,255,.12);"><div id="v179SelectLoaderFill" style="height:100%;width:4%;border-radius:999px;background:linear-gradient(90deg,#4aa8ff,#ffe45f);transition:width .16s ease;"></div></div>
      <div style="font:600 12px system-ui;opacity:.68;margin-top:10px;">This one-time preparation makes the roster screen run much more smoothly.</div>
    </div>`;
    document.body.appendChild(ov);
