    const V233_PREV_LOOP=loop;
    const V233_FRAME={last:0,samples:[],fps:0,worstMs:0};
    loop=function(ts){
      v233SyncViewportMode();
      if(V233_FRAME.last){
        const ms=ts-V233_FRAME.last;
        V233_FRAME.samples.push(ms);
        if(V233_FRAME.samples.length>90)V233_FRAME.samples.shift();
        let sum=0,worst=0;
        for(const v of V233_FRAME.samples){sum+=v;if(v>worst)worst=v;}
        V233_FRAME.worstMs=worst;
        const avg=sum/V233_FRAME.samples.length;
        V233_FRAME.fps=avg>0?1000/avg:0;
      }
      V233_FRAME.last=ts;
      return V233_PREV_LOOP(ts);
    };
    v233SyncViewportMode();
    window.__V233_PERF__={version:'233',stats:()=>({fps:+V233_FRAME.fps.toFixed(1),worstMs:+V233_FRAME.worstMs.toFixed(1),samples:V233_FRAME.samples.length,screen:(()=>{try{return STATE.screen}catch(_e){return null}})()}),observersRemoved:true,oneRafChain:true};
