  const num=(v,d=0)=>{v=Number(v);return Number.isFinite(v)?v:d;};
  const norm=v=>String(v??'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const baseRow=p=>p===STATE.player2?STATE.selectedHorseRow2:STATE.selectedHorseRow;
