  const costumeText=p=>{const c=p?._v273Costume||{},q=c.cfg||{};return norm([q.key,q.name,q.label,q.character,q.title,q.kind,c.key,c.kind,c.name,c.label,c.levelKey,p?._v273PowerKind].filter(Boolean).join(' '));};
  const costumeKind=p=>{if(!p?._v273Costume)return null;const s=costumeText(p);if(s.includes('professor timothy')||/(^| )timothy( |$)/.test(s))return null;if(s.includes('samus'))return 'samus';if(s.includes('king kong')||s.includes('kingkong')||/(^| )kong( |$)/.test(s))return 'kingKong';if(s.includes('ganon'))return 'ganon';return null;};
