// Remove only smooth, edge-connected blue backdrop pixels. The original art and crops remain the source.
const PORTRAIT_MATTE_CACHE459=new WeakMap();
function mattePortrait459(im,sx,sy,sw,sh){
  let byCrop=PORTRAIT_MATTE_CACHE459.get(im);
  if(!byCrop){byCrop=new Map();PORTRAIT_MATTE_CACHE459.set(im,byCrop);}
  const key=`${sx}:${sy}:${sw}:${sh}`;
  if(byCrop.has(key))return byCrop.get(key);
  const original={im,sx,sy,sw,sh};
  try{
    const c=document.createElement('canvas');c.width=sw;c.height=sh;
    const cc=c.getContext('2d',{willReadFrequently:true});cc.drawImage(im,sx,sy,sw,sh,0,0,sw,sh);
    const frame=cc.getImageData(0,0,sw,sh),data=frame.data,n=sw*sh;
    // Already transparent assets (including the supplied Samus and duo images) need no matte.
    let transparent=false;for(let i=3;i<data.length;i+=4)if(data[i]<245){transparent=true;break;}
    // Partial transparency must not bypass background removal.
    const blue=new Uint8Array(n),smooth=new Uint8Array(n),mask=new Uint8Array(n);
    for(let y=0;y<sh;y++)for(let x=0;x<sw;x++){
      const k=y*sw+x,i=k*4,r=data[i],g=data[i+1],b=data[i+2];
      if(!(b>40&&b>r*1.12&&b>g*1.03&&b-r>14))continue;
      blue[k]=1;let edge=false;
      for(const q of [x>0?k-1:-1,x<sw-1?k+1:-1,y>0?k-sw:-1,y<sh-1?k+sw:-1]){
        if(q<0)continue;const j=q*4;
        if(Math.abs(r-data[j])>12||Math.abs(g-data[j+1])>12||Math.abs(b-data[j+2])>12){edge=true;break;}
      }
      if(!edge)smooth[k]=1;
    }
    const queue=new Int32Array(n);let head=0,tail=0;
    const seed=k=>{if(smooth[k]&&!mask[k]){mask[k]=1;queue[tail++]=k;}};
    for(let x=0;x<sw;x++){seed(x);seed((sh-1)*sw+x);}
    for(let y=0;y<sh;y++){seed(y*sw);seed(y*sw+sw-1);}
    while(head<tail){
      const k=queue[head++],x=k%sw,y=(k-x)/sw;
      if(x>0)seed(k-1);if(x<sw-1)seed(k+1);
      if(y>0)seed(k-sw);if(y<sh-1)seed(k+sw);
    }
    // One-pixel edge cleanup, without spreading through textured blue costumes.
    const boundary=new Uint8Array(mask);
    for(let k=0;k<n;k++)if(blue[k]&&!mask[k]){
      const x=k%sw,y=(k-x)/sw;
      if((x>0&&boundary[k-1])||(x<sw-1&&boundary[k+1])||(y>0&&boundary[k-sw])||(y<sh-1&&boundary[k+sw]))mask[k]=1;
    }
    for(let k=0;k<n;k++)if(mask[k])data[k*4+3]=0;
    cc.putImageData(frame,0,0);
    const result={im:c,sx:0,sy:0,sw,sh};byCrop.set(key,result);return result;
  }catch(_e){byCrop.set(key,original);return original;}
}
function drawUnifiedCrop459(im,sx,sy,sw,sh,x,y,w,h){
  if(!im?.complete||!im.naturalWidth)return false;
  sw=Math.max(1,Math.round(sw));sh=Math.max(1,Math.round(sh));
  const source=mattePortrait459(im,sx,sy,sw,sh);
  const scale=Math.min(w/sw,h/sh),dw=sw*scale,dh=sh*scale;
  ctx.drawImage(source.im,source.sx,source.sy,sw,sh,x+(w-dw)/2,y+(h-dh)/2,dw,dh);
  return true;
}
function drawUnifiedImage459(im,x,y,w,h){
  return !!im?.naturalWidth&&drawUnifiedCrop459(im,0,0,im.naturalWidth,im.naturalHeight,x,y,w,h);
}
