    const col=i>=2?'#bb98ff':'#69d5ff';const g=ctx.createLinearGradient(sx,sy,sx,sy+sh);g.addColorStop(0,selected?'#12486d':'#173550');g.addColorStop(1,'#07152b');ctx.fillStyle=g;ctx.fillRect(sx,sy,slotW,sh);
    ctx.strokeStyle=current?'#ffe15b':selected?col:'rgba(146,184,211,.6)';ctx.lineWidth=current?2.2:1.2;ctx.strokeRect(sx+.5,sy+.5,slotW-1,sh-1);
    if(selected){const portraitW=Math.min(slotW-10,STATE.playerCount===2?42:72),portraitH=Math.min(sh-24,46);drawDossierPortrait434(row,sx+(slotW-portraitW)/2,sy+3,portraitW,portraitH);}
