  const st=typeof v97Stats==='function'?v97Stats(row):{speed:3,jump:3,range:3,recharge:3},sy=y+47,sw=Math.floor((avail-6)/4);drawStat434('Speed',st.speed,tx,sy,sw);drawStat434('Jump',st.jump,tx+sw,sy,sw);drawStat434('Range',st.range,tx+sw*2,sy,sw);drawStat434('Recharge',st.recharge,tx+sw*3,sy,sw);
